import { Hono } from 'hono'
import { cors } from 'hono/cors'
import mp from './routes/marketplace'
import { marketplacePageHTML, marketplaceListingPageHTML, marketplaceDashboardPageHTML, marketplaceAdminPageHTML, marketplaceFaqPageHTML } from './routes/marketplace-pages'

type Bindings = {
  UPLOADS?: R2Bucket
  DB: D1Database
  // Bearer token for the read-only attendee export consumed by AImailPilot's
  // contact-list sync. Set via `wrangler secret put ATTENDEE_EXPORT_SECRET`
  // — never lives in this repo or the database.
  ATTENDEE_EXPORT_SECRET?: string
  // Shared secret that authenticates the admin panel. Set via
  // `wrangler secret put ADMIN_SECRET` (or a Pages env var) — never in this
  // repo or the DB. Every /api/admin/* route requires it (see middleware
  // below). This replaces the old client-side-only `admin123` check.
  ADMIN_SECRET?: string
  // Secret used to HMAC-sign marketplace session cookies so the company id
  // can't be forged. Falls back to ADMIN_SECRET if unset.
  MP_SESSION_SECRET?: string
}

const app = new Hono<{ Bindings: Bindings }>()

app.use('/api/*', cors())

// ==================== ADMIN AUTHENTICATION ====================
// Server-side guard for every /api/admin/* route. The admin panel sends the
// secret as `Authorization: Bearer <ADMIN_SECRET>` on all fetches (see the
// `api` helper in the admin page). The one CSV-export link is a plain <a>
// download, so it may also pass the secret as `?token=` — accepted here too.
//
// Fails CLOSED: if ADMIN_SECRET is not configured, all admin routes return
// 503 rather than being world-open. Set it in Cloudflare before relying on
// the panel: `npx wrangler pages secret put ADMIN_SECRET`.
// ==================== ADMIN AUDIT ====================
// The panel is opened with one shared password, so the operator name is what the
// panel says it is - self-declared, and labelled that way in the UI. The IP and
// user agent are not, and a destructive action is traceable with all three.
// Never throws: an audit write must not be able to fail the action it records.
async function audit(c: any, action: string, entity?: string, entityId?: any, detail?: any,
    actorOverride?: { actor: string; kind: string }) {
  try {
    const who = actorOverride || adminActor(c)
    const actor = who.actor
    const kind = who.kind
    await c.env.DB.prepare(
      'INSERT INTO admin_audit (actor, actor_kind, action, entity, entity_id, detail, ip, user_agent) VALUES (?,?,?,?,?,?,?,?)'
    ).bind(
      actor, kind, action, entity || null,
      entityId == null ? null : String(entityId),
      detail == null ? null : (typeof detail === 'string' ? detail : JSON.stringify(detail)).slice(0, 2000),
      c.req.header('CF-Connecting-IP') || null,
      (c.req.header('User-Agent') || '').slice(0, 200) || null
    ).run()
  } catch (_) { /* the table may predate migration 0027; never break the caller */ }
}

// One place that knows how to send a transactional email, so new features do not
// each re-implement the Elastic Email call and its settings lookup. Named for the
// admin panel it was written for; it is the generic sender and the networking
// notifications below use it too. Never throws: returns { ok:false, error } on a
// missing key, a non-2xx, or an unreachable service. Sets no ReplyTo on purpose --
// a notification must never hand one attendee another attendee's address.
async function sendAdminEmail(c: any, to: string, subject: string, html: string):
    Promise<{ ok: true } | { ok: false; error: string }> {
  const g = async (k: string) => ((await c.env.DB.prepare('SELECT value FROM app_settings WHERE key = ?').bind(k).first()) as any)?.value
  const key = await g('elastic_email_api_key')
  if (!key) return { ok: false, error: 'Email service is not configured (no API key in Settings).' }
  const fromEmail = senderEmailOrDefault(await g('sender_email'))
  const fromName = (await g('sender_name')) || 'Bharat AI Innovation Conference & Exhibition 2026'
  try {
    const res = await fetch('https://api.elasticemail.com/v4/emails/transactional', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-ElasticEmail-ApiKey': key },
      body: JSON.stringify({
        Recipients: { To: [to] },
        Content: {
          Body: [{ ContentType: 'HTML', Content: html, Charset: 'utf-8' }],
          From: `${fromName} <${fromEmail}>`,
          Subject: subject,
        },
        Options: { TrackClicks: false, TrackOpens: false },
      }),
    })
    const body = await res.json().catch(() => ({})) as any
    if (!res.ok) return { ok: false, error: body?.Error || ('Email service returned HTTP ' + res.status) }
    return { ok: true }
  } catch (e: any) {
    return { ok: false, error: e?.message || 'Could not reach the email service.' }
  }
}

// Resolve a staff session once per request. verifyStaffSession returns null
// immediately when there is no cookie, so an ordinary visitor costs no query.
app.use('*', async (c, next) => {
  try {
    const me = await verifyStaffSession(c)
    if (me && me.role === 'admin') staffAdminByRequest.set(c.req.raw, me)
  } catch { /* never let session resolution break the request */ }
  await next()
})

app.use('/api/admin/*', async (c, next) => {
  // A named admin account is enough on its own, so the panel still works if
  // ADMIN_SECRET is ever unset. Otherwise the shared secret must match.
  const viaAccount = (() => { try { return !!staffAdminByRequest.get(c.req.raw) } catch { return false } })()
  if (!viaAccount) {
    const expected = c.env.ADMIN_SECRET || ''
    if (!expected) {
      return c.json({ error: 'admin access is not configured' }, 503)
    }
    const header = c.req.header('Authorization') || ''
    const bearer = header.startsWith('Bearer ') ? header.slice(7) : ''
    const token = bearer || c.req.query('token') || ''
    if (token !== expected) {
      return c.json({ error: 'unauthorized' }, 401)
    }
  }
  await next()
})

// Lightweight endpoint the admin login form calls to verify the entered
// password server-side. Protected by the middleware above, so a 200 means
// the secret is correct; a 401 means it isn't. Returns no data.
app.get('/api/admin/verify', (c) => c.json({ ok: true }))

// Lets the panel say who it thinks you are, and whether that is an authenticated
// account or just the shared password plus a typed-in name.
app.get('/api/admin/whoami', (c) => {
  let account: any = null
  try { account = staffAdminByRequest.get(c.req.raw) || null } catch { account = null }
  const who = adminActor(c)
  return c.json({
    actor: who.actor,
    kind: who.kind,
    authenticated: !!account,
    username: account ? account.username : null,
    name: account ? account.name : null,
  })
})

// Who did what, newest first. Optionally narrowed to one record.
app.get('/api/admin/audit', async (c) => {
  const entity = c.req.query('entity') || ''
  const entityId = c.req.query('entity_id') || ''
  const limit = Math.min(500, Math.max(1, parseInt(c.req.query('limit') || '100', 10) || 100))
  try {
    let q = 'SELECT * FROM admin_audit'
    const p: any[] = []
    if (entity) { q += ' WHERE entity = ?'; p.push(entity); if (entityId) { q += ' AND entity_id = ?'; p.push(entityId) } }
    q += ' ORDER BY id DESC LIMIT ?'
    p.push(limit)
    const { results } = await c.env.DB.prepare(q).bind(...p).all()
    return c.json({ entries: results })
  } catch (e: any) {
    // Before migration 0027 the table is absent; say so rather than 500.
    if (/no such table/i.test(String(e?.message || ''))) return c.json({ entries: [], unavailable: true })
    throw e
  }
})

