function staffScanHTML(me: any): string {
  return staffShell('Scan passes', `
    <div class="bar"><h1>Scan a pass</h1><a href="#" onclick="out()">Sign out</a></div>
    <p class="muted">Signed in as ${String(me.name).replace(/[<>&]/g, '')}. Point the camera at the QR on the attendee's pass.</p>
    <video id="v" playsinline muted></video>
    <p class="err" id="e"></p>
    <div class="find">
      <label for="q">No pass to scan?</label>
      <input id="q" placeholder="Name, email, company, mobile or BHAI number" autocapitalize="words" autocomplete="off">
      <div id="res"></div>
    </div>
    <div class="hint"><strong>No camera?</strong> Your phone's own camera app also works &mdash; point it at the QR and tap the link it offers. You will land on the same verification screen.</div>`,
  `var v=document.getElementById('v'), e=document.getElementById('e'), stopped=false;
   async function out(){ await fetch('/api/staff/logout',{method:'POST'}); location.href='/staff'; }
   async function start(){
     if(!('BarcodeDetector' in window)){
       e.textContent='This browser cannot scan in-page. Use your phone camera app on the QR instead.'; return;
     }
     try{
       var stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});
       v.srcObject=stream; await v.play();
     }catch(err){ e.textContent='Camera unavailable. Use your phone camera app on the QR instead.'; return; }
     var det=new BarcodeDetector({formats:['qr_code']});
     (async function loop(){
       if(stopped) return;
       try{
         var codes=await det.detect(v);
         if(codes && codes.length){
           var url=codes[0].rawValue||'';
           if(url.indexOf('/verify/')>=0){ stopped=true; location.href=url; return; }
         }
       }catch(err){}
       setTimeout(loop,250);
     })();
   }
   start();

   // Debounced: the desk types with one thumb while holding a queue back.
   var qEl=document.getElementById('q'), resEl=document.getElementById('res'), timer=null;
   qEl.addEventListener('input',function(){ clearTimeout(timer); timer=setTimeout(find,300); });
   async function find(){
     var q=qEl.value.trim();
     if(q.length<2){ resEl.innerHTML=''; return; }
     var r=await fetch('/api/staff/lookup?q='+encodeURIComponent(q));
     if(r.status===401){ location.href='/staff'; return; }
     var j=await r.json().catch(function(){return{results:[]}});
     if(!j.results.length){ resEl.innerHTML='<p class="err">Nobody found. Try a surname, or the number on their confirmation email.</p>'; return; }
     resEl.innerHTML=j.results.map(function(a){
       var esc=function(v){ return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); };
       var sub=[a.job_title,a.company].filter(Boolean).map(esc).join(', ');
       var state=a.checked_in_at? '<em>Already in &middot; '+esc(a.checked_in_ist)+'</em>' : esc(a.badge_type||'');
       return '<a class="hit" href="/verify/'+encodeURIComponent(a.token)+'"><b>'+esc(a.name)+'</b>'+
              '<span>'+(sub?sub+' &middot; ':'')+esc(a.ref)+'</span><span>'+state+'</span></a>';
     }).join('');
   }`)
}

// ==================== PASS VERIFICATION ====================
//
// The QR on a pass carries a signed token, not an email address. Signing means a
// pass cannot be forged by guessing an id, and carrying no personal data means a
// stranger who photographs someone's pass learns nothing from the code itself.
const passTokenSecret = (c: any): string => c.env.PASS_SECRET || c.env.SESSION_SECRET || c.env.ADMIN_SECRET || ''

async function signPassToken(c: any, attendeeId: number | string): Promise<string> {
  const secret = passTokenSecret(c)
  if (!secret) return String(attendeeId)
  return String(attendeeId) + '.' + (await hmacHexA(secret, 'pass:' + attendeeId)).slice(0, 24)
}

async function verifyPassToken(c: any, token: string): Promise<number | null> {
  const secret = passTokenSecret(c)
  if (!secret || !token) return null
  const dot = token.lastIndexOf('.')
  if (dot < 1) return null
  const id = token.slice(0, dot), sig = token.slice(dot + 1)
  const expected = (await hmacHexA(secret, 'pass:' + id)).slice(0, 24)
  if (!safeEqualA(sig, expected)) return null
  const n = parseInt(id, 10)
  return Number.isFinite(n) ? n : null
}

// The token for the signed-in attendee, so the app can build its own QR.
app.get('/api/my-pass-token', async (c) => {
  // Admin may mint for any attendee, so the desk can issue a pass on someone's
  // behalf; everyone else only ever gets their own.
  const forId = c.req.query('id')
  if (forId && isAdminRequest(c)) return c.json({ token: await signPassToken(c, forId) })
  const me = await verifyAttendeeSession(c)
  if (me === null) return c.json({ error: 'Sign in required' }, 401)
  return c.json({ token: await signPassToken(c, me) })
})

// Staff scan target. Public URL, but personal details are shown only to a caller
// holding the staff code — otherwise a stranger scanning a pass on a lanyard would
// see the holder's photo, employer and tier.
app.get('/verify/:token', async (c) => {
  const token = c.req.param('token')
  const id = await verifyPassToken(c, token)
  const staff = (await verifyStaffSession(c)) || (isAdminRequest(c) ? { name: 'admin' } : null)

  if (id === null) {
    return c.html(verifyPageHTML({ state: 'invalid', staff, token }))
  }
  const a = await c.env.DB.prepare(
    'SELECT id, name, company, job_title, badge_type, payment_status, avatar_url, checked_in_at, checked_in_by FROM attendees WHERE id = ?'
  ).bind(id).first() as any
  if (!a) return c.html(verifyPageHTML({ state: 'invalid', staff, token }))
  const undoable = !!a.checked_in_at &&
    Date.now() - new Date(String(a.checked_in_at).replace(' ', 'T') + 'Z').getTime() < CHECKIN_UNDO_MINUTES * 60000
  return c.html(verifyPageHTML({ state: 'valid', staff, token, attendee: a, undoable }))
})

app.post('/api/verify/:token/checkin', async (c) => {
  const who = await deskActor(c)
  if (!who) return c.json({ error: 'Badge desk sign-in required' }, 401)
  const id = await verifyPassToken(c, c.req.param('token'))
  if (id === null) return c.json({ error: 'Invalid pass' }, 400)
  const body = await c.req.json().catch(() => ({})) as any
  const a = await c.env.DB.prepare('SELECT id, name, checked_in_at FROM attendees WHERE id = ?').bind(id).first() as any
  if (!a) return c.json({ error: 'Not found' }, 404)
  // at stays UTC for anything programmatic; at_ist is what a human should be shown.
  if (a.checked_in_at) return c.json({ success: false, already: true, at: a.checked_in_at, at_ist: istStamp(a.checked_in_at), name: a.name })
  // Attributable: who admitted this person, not just that someone did.
  await c.env.DB.prepare("UPDATE attendees SET checked_in_at = datetime('now'), checked_in_by = ? WHERE id = ?")
    .bind(String(who.name || 'desk').slice(0, 40), id).run()
  return c.json({ success: true, name: a.name })
})

// SQLite datetime('now') stores UTC, which is right: one clock, no ambiguity. But
// everyone reading these timestamps is in Mumbai, where a 9:30am arrival printed as
// UTC reads 04:00 - a number that looks like a bug at the desk. IST is a fixed
// +05:30 with no daylight saving, so shifting the instant is exact and needs no
// timezone database inside the worker.
const IST_OFFSET_MINUTES = 330
const IST_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

function istStamp(v: any): string {
  if (!v) return ''
  const raw = String(v).replace(' ', 'T')
  // SQLite hands back a bare "2026-11-20 09:14:02" with no zone marker, which
  // Date() would otherwise read as local time and shift twice.
  const iso = /Z$|[+-]\d\d:?\d\d$/.test(raw) ? raw : raw + 'Z'
  const d = new Date(iso)
  if (isNaN(d.getTime())) return String(v)
  const t = new Date(d.getTime() + IST_OFFSET_MINUTES * 60000)
  const h24 = t.getUTCHours()
  const h = h24 % 12 || 12
  const mm = String(t.getUTCMinutes()).padStart(2, '0')
  return t.getUTCDate() + ' ' + IST_MONTHS[t.getUTCMonth()] + ' ' + t.getUTCFullYear() +
         ', ' + h + ':' + mm + ' ' + (h24 < 12 ? 'am' : 'pm') + ' IST'
}

// Someone will tap Check in on the wrong pass. Until now the only remedy was an
// admin editing the database. The window is short on purpose: this is for a misfire
// noticed immediately, not a way to quietly re-admit somebody an hour later.
const CHECKIN_UNDO_MINUTES = 15

app.post('/api/verify/:token/undo', async (c) => {
  const who = await deskActor(c)
  if (!who) return c.json({ error: 'Badge desk sign-in required' }, 401)
  const id = await verifyPassToken(c, c.req.param('token'))
  if (id === null) return c.json({ error: 'Invalid pass' }, 400)
  const a = await c.env.DB.prepare('SELECT id, checked_in_at FROM attendees WHERE id = ?').bind(id).first() as any
  if (!a) return c.json({ error: 'Not found' }, 404)
  if (!a.checked_in_at) return c.json({ success: true, already: false })
  const age = Date.now() - new Date(String(a.checked_in_at).replace(' ', 'T') + 'Z').getTime()
  if (age > CHECKIN_UNDO_MINUTES * 60000) {
    return c.json({ error: 'Too long ago to undo here. Ask the admin desk to reset it.' }, 409)
  }
  await c.env.DB.prepare('UPDATE attendees SET checked_in_at = NULL, checked_in_by = NULL WHERE id = ?').bind(id).run()
  return c.json({ success: true })
})

function verifyPageHTML(o: any): string {
  const a = o.attendee || {}
  const esc = (v: any) => String(v ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch] as string))
  const TIER: any = {
    'VIP Pass': ['#E9C356', '#5a3f08'], 'Delegate Pass': ['#00996C', '#ffffff'],
    'Academic Pass': ['#7C5CFF', '#ffffff'], 'Visitor Pass': ['#2B8CFF', '#ffffff']
  }
  const tier = TIER[a.badge_type] || ['#2B8CFF', '#ffffff']
  const unpaid = String(a.payment_status || '').toLowerCase() === 'pending'
  const ok = o.state === 'valid' && !unpaid
  const banner = o.state !== 'valid' ? ['#b3261e', 'NOT VALID', 'This code is not a Bharat AI Innovation pass.']
    : unpaid ? ['#b26a00', 'PAYMENT PENDING', 'This tier has not been paid for. Do not admit without checking.']
    : ['#0f7b47', 'VALID PASS', 'Check the photo and name against a government photo ID.']

  // An unrecognised code has no holder, so it must not render a card with an empty
  // name, a default "Visitor Pass" pill and a live Check in button — that reads at a
  // glance like a pass the desk can admit, under a banner saying it is not one.
  const body = o.state !== 'valid'
    ? `<div class="card"><p class="muted">There is nothing to check in.</p>
         <p class="muted" style="margin-top:6px;">Ask for the pass again, or look the person up by name in the admin panel.</p>
         ${o.staff ? `<button onclick="location.href='/staff/scan'">Scan another pass</button>` : ''}</div>`
    : !o.staff
    ? `<div class="card"><p class="muted">Badge desk staff only.</p>
         <p class="muted" style="margin-top:6px;">Sign in with your desk account to see the holder's details and check them in. You stay signed in for three days, so you only do this once.</p>
         <button onclick="signIn()">Staff sign in</button></div>`
    : `<div class="card">
         ${a.avatar_url ? `<img class="photo" src="${esc(a.avatar_url)}" alt="">` : `<div class="photo initial">${esc(String(a.name || '?').charAt(0).toUpperCase())}</div>`}
         <h2>${esc(a.name)}</h2>
         ${a.job_title ? `<p class="muted">${esc(a.job_title)}</p>` : ''}
         ${a.company ? `<p class="muted">${esc(a.company)}</p>` : ''}
         <div class="tier" style="background:${tier[0]};color:${tier[1]};">${esc(a.badge_type || 'Visitor Pass')}</div>
         ${a.checked_in_at
            ? `<div class="warn">Already checked in ${esc(istStamp(a.checked_in_at))}${a.checked_in_by ? ' by ' + esc(a.checked_in_by) : ''}</div>
               ${o.undoable ? `<button id="undo" onclick="undo()" style="background:#243056;">Undo this check-in</button>` : ''}`
            : `<button id="ci" onclick="checkIn()">Check in</button>`}
         <p id="msg" class="muted"></p>
       </div>`

  return `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pass verification - Bharat AI Innovation 2026</title>
<style>
 body{margin:0;background:#0a0e1f;color:#e8edf5;font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;}
 .wrap{max-width:460px;margin:0 auto;padding:18px;}
 .banner{border-radius:16px;padding:22px 18px;text-align:center;background:${banner[0]};}
 .banner h1{margin:0;font-size:26px;letter-spacing:1px;}
 .banner p{margin:8px 0 0;font-size:13px;opacity:.92;line-height:1.5;}
 .card{margin-top:14px;background:#111731;border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:20px;text-align:center;}
 .photo{width:130px;height:130px;border-radius:50%;object-fit:cover;display:block;margin:0 auto 12px;border:3px solid rgba(255,255,255,.18);}
 .initial{background:#243056;font-size:54px;line-height:130px;}
 h2{margin:0 0 4px;font-size:23px;}
 .muted{margin:2px 0;color:#98a3bd;font-size:14px;}
 .tier{display:inline-block;margin:14px 0 4px;padding:9px 22px;border-radius:999px;font-weight:700;font-size:14px;}
 button{margin-top:14px;width:100%;padding:15px;border:none;border-radius:12px;background:#FF6B00;color:#fff;font-size:16px;font-weight:700;}
 input{margin-top:10px;width:100%;padding:13px;border-radius:10px;border:1px solid rgba(255,255,255,.15);background:#0a0e1f;color:#fff;font-size:15px;box-sizing:border-box;}
 .warn{margin-top:14px;padding:12px;border-radius:10px;background:rgba(178,106,0,.18);border:1px solid rgba(178,106,0,.5);font-size:13px;line-height:1.5;}
 .foot{margin-top:16px;text-align:center;font-size:12px;color:#5a6a8a;}
</style></head><body><div class="wrap">
 <div class="banner"><h1>${banner[1]}</h1><p>${banner[2]}</p></div>
 ${body}
 <p class="foot">Bharat AI Innovation 2026 &bull; badge desk verification</p>
</div>
<script>
 var TOKEN = ${JSON.stringify(o.token || '')};
 function signIn(){ location.href = '/staff?next=' + encodeURIComponent(location.pathname); }
 async function checkIn(){
   var b = document.getElementById('ci'), m = document.getElementById('msg');
   b.disabled = true; b.textContent = 'Checking in...';
   try {
     // The staff session cookie travels with this same-origin request; nothing
     // secret is held in the page, so a screenshot of it gives nothing away.
     var r = await fetch('/api/verify/' + encodeURIComponent(TOKEN) + '/checkin', { method:'POST' });
     var j = await r.json();
     if (j.success) { b.textContent = 'Checked in \u2713'; b.style.background = '#0f7b47'; next(); }
     else if (j.already) { b.style.display='none'; m.textContent = 'Already checked in ' + (j.at_ist || j.at); next(); }
     else if (r.status === 401) { b.disabled=false; b.textContent='Check in'; m.textContent='Your session expired.'; signIn(); }
     else { b.disabled=false; b.textContent='Check in'; m.textContent = j.error || 'Could not check in'; }
   } catch(e){ b.disabled=false; b.textContent='Check in'; m.textContent='Network error'; }
 }
 async function undo(){
   var b = document.getElementById('undo'), m = document.getElementById('msg');
   b.disabled = true; b.textContent = 'Undoing...';
   var r = await fetch('/api/verify/' + encodeURIComponent(TOKEN) + '/undo', { method:'POST' });
   var j = await r.json().catch(function(){ return {}; });
   if (r.ok) location.reload();
   else { b.disabled = false; b.textContent = 'Undo this check-in'; m.textContent = j.error || 'Could not undo'; }
 }
 // The desk works in a queue: finishing one person should offer the next scan.
 function next(){
   if (document.getElementById('nx')) return;
   var a = document.createElement('button');
   a.id = 'nx'; a.textContent = 'Scan next pass'; a.style.background = '#243056';
   a.onclick = function(){ location.href = '/staff/scan'; };
   document.getElementById('msg').parentNode.appendChild(a);
 }
</script></body></html>`
}

// ==================== BOARDROOMS ====================
//
// Rollout switch: boardroom booking activates only once migration 0029 has created
// its two tables. Until then every rooms route reports ready:false and the meeting
// modal keeps its free-text Location box, so the code deploy and the hand-run
// migration are independent and can happen in either order — same rollout switch
// as verifiedLoginEnabled below and paymentStatusEnabled above.
//
// Only a POSITIVE answer is memoised. Caching "not there yet" would pin an isolate
// to false for its whole life, so after the migration ran the endpoint really did
// answer ready:true on fresh isolates and ready:false on the one that had probed
// earlier — the feature looking half-broken for as long as that isolate lived.
// Tables never disappear, so a true answer is safe to keep forever; a false one is
// worth one cheap sqlite_master read per request until it flips.
let _roomTables = false
async function roomBookingEnabled(c: any): Promise<boolean> {
  if (_roomTables) return true
  try {
    const { results } = await c.env.DB.prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name IN ('meeting_rooms','room_bookings')"
    ).all()
    if ((results || []).length === 2) _roomTables = true
  } catch { /* table missing or DB unavailable — stay off, re-probe next request */ }
  return _roomTables
}

// The same rollout switch for the exhibition floor. Booth inventory and its
// allocations arrive with migration 0030, and a Cloudflare deploy never runs a
// migration, so this code is live for however long it takes somebody to run the
// wrangler command by hand. Only the POSITIVE answer is memoised, for the reason
// spelled out above roomBookingEnabled: caching "not there yet" pins an isolate
// to false for its whole life and leaves the floor plan looking half-broken long
// after the tables exist.
let _boothTables = false
async function boothInventoryEnabled(c: any): Promise<boolean> {
  if (_boothTables) return true
  try {
    const { results } = await c.env.DB.prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name IN ('booths','booth_allocations')"
    ).all()
    if ((results || []).length === 2) _boothTables = true
  } catch { /* table missing or DB unavailable — stay off, re-probe next request */ }
  return _boothTables
}

// ---------------------------------------------------------------------------
// THE ALLOCATION LIFECYCLE COLUMNS. Migration 0030 created booth_allocations with
// seven columns the shipped code never wrote: the option clock (hold_expires_at),
// the soft release (released_at), the withholding (tds_deducted_inr), the credit
// terms (balance_due_date) and the invoice counterparty (buyer_gstin,
// buyer_legal_name, buyer_state_code). They are used from here on.
//
// A SECOND rollout switch is still needed, for the reason boothInventoryEnabled
// exists at all: the tables can be present while these columns are not, because
// 0030's commercial half was added to that file in place and a database carrying
// an earlier draft of it has booths and booth_allocations but not released_at.
// Every read and write below therefore asks this first and falls back to the
// column set that was always there, rather than 500ing at an operator.
//
// Only the POSITIVE answer is memoised — the same call as above. Caching "not
// there yet" would pin an isolate to the degraded query set for its whole life,
// long after the columns existed.
const BOOTH_LIFECYCLE_COLS = [
  'hold_expires_at', 'released_at', 'tds_deducted_inr', 'balance_due_date',
  'buyer_gstin', 'buyer_legal_name', 'buyer_state_code',
]
let _boothLifecycleCols = false
async function boothLifecycleEnabled(c: any): Promise<boolean> {
  if (_boothLifecycleCols) return true
  try {
    const { results } = await c.env.DB.prepare(
      "SELECT name FROM pragma_table_info('booth_allocations')"
    ).all()
    const have = new Set(((results || []) as any[]).map(r => String(r.name)))
    if (BOOTH_LIFECYCLE_COLS.every(n => have.has(n))) _boothLifecycleCols = true
  } catch { /* columns or table missing — stay off, re-probe next request */ }
  return _boothLifecycleCols
}

// THE SOFT RELEASE, as a join condition. A released allocation is a tax document's
// counterparty kept for the audit and the credit-note trail — it is NOT an
// occupant, so it must be invisible to every availability, revenue, count and
// drill-down query in this file. The partial unique index
// idx_booth_alloc_live(event_id, booth_id) WHERE released_at IS NULL is what lets a
// released stand be sold again; this fragment is what stops the released row still
// showing as the buyer while that happens.
//
// Empty string when the columns are not there yet, which is exactly the behaviour
// this endpoint had before: nothing was ever released, so nothing was excluded.
const boothLiveOnly = (live: boolean, alias = 'ba'): string =>
  live ? ` AND ${alias}.released_at IS NULL` : ''

// THE OPTION CLOCK. A 'held' stand is an option the sales desk gave somebody —
// "yours until Friday" — and until now it never expired, so a stand optioned in
// March was still off the market in September with nobody chasing it.
//
// There is no cron. Cloudflare deploys do not run one, and a scheduled worker is
// not going to appear because a hold lapsed, so the lapse is computed AT READ
// TIME: a held row past its expiry simply reads as available everywhere, and the
// row stays put so the desk can still see who let it go. The two expressions
// below are the same rule in the two languages this file has to say it in, and
// they must not be allowed to disagree.
//
// The clock stops at the END of the expiry day, not at midnight UTC on it, so a
// hold "until the 30th" is live all of the 30th. SQLite's date('now') is UTC and
// the venue is IST, which means a lapse lands about 05:30 IST the following
// morning — late rather than early, which is the safe direction: nothing is ever
// yanked out from under a salesperson mid-conversation.
const BOOTH_HOLD_DAYS_DEFAULT = 14
const boothLapsedSql = (alias = 'ba'): string =>
  `(${alias}.id IS NOT NULL AND ${alias}.status = 'held' AND ${alias}.hold_expires_at IS NOT NULL` +
  ` AND date(${alias}.hold_expires_at) < date('now'))`
const boothToday = (): string => new Date().toISOString().slice(0, 10)
const boothHoldLapsed = (status: any, expiresAt: any, today: string): boolean =>
  String(status || '') === 'held' && !!expiresAt && String(expiresAt).slice(0, 10) < today
// Whole days from today to a date, negative once it is in the past. Text in, no
// Date arithmetic on a stored string that may be a date or a datetime.
const boothDaysUntil = (value: any, today: string): number | null => {
  const d = String(value == null ? '' : value).slice(0, 10)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) return null
  return Math.round((Date.parse(d + 'T00:00:00Z') - Date.parse(today + 'T00:00:00Z')) / 86400000)
}
// today + n days, as the YYYY-MM-DD a date input speaks.
const boothDatePlus = (days: number): string =>
  new Date(Date.now() + days * 86400000).toISOString().slice(0, 10)

// ---------------------------------------------------------------------------
// GSTIN. The invoice counterparty, and the reason buyer_state_code is captured at
// all: place of supply decides IGST against CGST+SGST, that question is with the
// organiser's accountant, and whichever way it is answered the answer needs the
// buyer's state. Storing the code now means the split can be implemented later
// without going back to 93 exhibitors to ask where they are registered.
//
// The shape is fixed and worth checking — 15 characters, a 2-digit state code, a
// PAN in positions 3-12 — but a bad or missing GSTIN NEVER blocks a sale. A
// walk-up at a roadshow does not have it to hand, and refusing to record the deal
// until they do is how a sale ends up written on paper instead. So this returns a
// warning to show, not an error to stop on.
//
// State codes run 01-38 (0-numbered union territories included), plus 97 for
// "other territory" and 99 for a centralised UIN holder.
function boothGstinWarning(gstin: any): string | null {
  const s = String(gstin == null ? '' : gstin).trim().toUpperCase()
  if (!s) return null
  if (s.length !== 15) return `GSTIN "${s}" is ${s.length} characters; a GSTIN is 15. The sale is recorded — correct it before the invoice goes out.`
  if (!/^[0-9]{2}/.test(s)) return `GSTIN "${s}" does not start with a 2-digit state code. The sale is recorded — correct it before the invoice goes out.`
  const state = Number(s.slice(0, 2))
  if (!((state >= 1 && state <= 38) || state === 97 || state === 99)) {
    return `GSTIN "${s}" starts with state code ${s.slice(0, 2)}, which is not a GST state code. The sale is recorded — correct it before the invoice goes out.`
  }
  if (!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(s.slice(2, 12))) {
    return `GSTIN "${s}" does not carry a PAN in positions 3-12. The sale is recorded — correct it before the invoice goes out.`
  }
  if (!/^[0-9A-Z]$/.test(s.slice(12, 13)) || !/^[0-9A-Z]$/.test(s.slice(14, 15))) {
    return `GSTIN "${s}" has a character that cannot appear in a GSTIN. The sale is recorded — correct it before the invoice goes out.`
  }
  return null
}
// The state code the invoice needs. Typed if the operator typed one, otherwise
// read off the GSTIN, which is where it lives anyway. Two digits or null — never
// a guess, because a wrong place of supply is a denied input tax credit.
// A typed state code that contradicts its own GSTIN is the one pair that must not
// pass quietly. boothStateCode prefers the typed value, and place of supply will be
// derived from it once the accountant rules on IGST vs CGST+SGST — so a contradiction
// silently decides a tax question the wrong way and denies the buyer input credit.
// This only WARNS: which field wins is the owner's call, and a walk-up desk should
// still be able to save the sale.
function boothStateGstinConflict(typed: any, gstin: any): string | null {
  const t = String(typed == null ? '' : typed).trim()
  const g = String(gstin == null ? '' : gstin).trim().toUpperCase()
  if (!/^[0-9]{1,2}$/.test(t) || !/^[0-9]{2}/.test(g)) return null
  const a = t.padStart(2, '0'), b = g.slice(0, 2)
  return a === b ? null : `State code ${a} does not match the GSTIN, which begins ${b}. Check which is right before the invoice is raised.`
}

function boothStateCode(typed: any, gstin: any): string | null {
  const t = String(typed == null ? '' : typed).trim()
  if (/^[0-9]{1,2}$/.test(t)) return t.padStart(2, '0')
  const g = String(gstin == null ? '' : gstin).trim().toUpperCase()
  if (/^[0-9]{2}/.test(g)) return g.slice(0, 2)
  return null
}

// Booth categories largest first, which is the order the packages are pitched and
// priced in. This lives in code rather than a column because it is a display
// decision, not inventory: booths.name already carries the package label a code
// belongs to ("Flagship Pavilion"), and booths.sort_order already fixes the order
// within a category.
const BOOTH_TYPE_ORDER = ['mega', 'enterprise', 'premium', 'accelerator', 'standard', 'innovator', 'explorer', 'pod']
const boothTypeRank = (k: string): number => {
  const i = BOOTH_TYPE_ORDER.indexOf(String(k || ''))
  return i === -1 ? BOOTH_TYPE_ORDER.length : i
}

// exhibitors.booth_size is a two-value display field ('standard' | 'premium'),
// not a measurement — the same split the booth-request approval applies when it
// turns an approved request into an exhibitor. The three biggest footprints read
// as premium; everything else is standard.
const boothExhibitorSize = (typeKey: string): string =>
  ['mega', 'enterprise', 'premium'].includes(String(typeKey || '')) ? 'premium' : 'standard'

// ---------------------------------------------------------------------------
// BOOTH MONEY. Every figure below is WHOLE RUPEES. A float rupee becomes
// 32249.999999 on a GST invoice and the exhibitor is the one who finds out, so
// nothing here is ever allowed to stay fractional — the same rule migration 0030
// states over booth_allocations.
// ---------------------------------------------------------------------------
const BOOTH_GST_PCT = 18
const boothGst = (net: number): number => Math.round((Number(net) || 0) * BOOTH_GST_PCT / 100)

// pending | invoiced | part_paid | paid | refunded. Money only: whether the stand
// is OCCUPIED is booth_allocations.status (held | confirmed | blocked).
const BOOTH_PAYMENT_STATUSES = ['pending', 'invoiced', 'part_paid', 'paid', 'refunded']

// The revenue target lives in app_settings (0005's key/value store), which is
// where this app already keeps its one-off editable numbers — not in a table of
// its own. The default is the full sellable value of the hall at list: 93 stands,
// Rs 1,82,90,000 ex-GST. Migration 0030 seeds the same number with INSERT OR
// IGNORE; this constant is what answers before the migration has been run.
const BOOTH_TARGET_KEY = 'booth_revenue_target_inr'
const BOOTH_TARGET_DEFAULT = 18290000

// booth_types.slug (the 2011-era catalogue the public request form sells from)
// against booths.type_key (the floor plan's own legacy key). They disagree on
// purpose and the disagreement is NOT a typo: the catalogue's "Accelerator Booth"
// is 3x3, which the plan calls 'standard', and the catalogue's "Enterprise Booth"
// is 4x2, which the plan calls 'accelerator'. Anything that re-derives one from
// the other makes the admin screen contradict the public plan — see the note at
// the top of public/js/floor-plan.js. 'premium' is deliberately absent: the 5x2
// tier arrived with the revised WTC layout and was never added to the catalogue,
// which is exactly why the inventory table used to lose those two stands.
const BOOTH_TYPE_SLUG: Record<string, string> = {
  pod: 'startup-pod',
  explorer: 'explorer-booth',
  innovator: 'innovator-booth',
  standard: 'accelerator-booth',
  accelerator: 'enterprise-booth',
  enterprise: 'flagship-pavilion',
  mega: 'mega-pavilion',
}

// Rupees off a form field. Forgiving on the way in — "₹1,25,000", "125000.00" and
// " 125000 " are all the same number to a salesperson — and never negative.
//
// A minus is NOT a stray character to be scrubbed. The strip below used to run
// before anything looked at the sign, so "-5000" arrived as +5000: a refund typed
// into "amount paid" was banked as money COLLECTED. Anything carrying a minus is
// a typo, so it reads as 0 here — and every caller that can REPORT the problem to
// whoever typed it goes through boothRupeesStrict, which names the field instead.
function boothRupees(v: any): number {
  if (v === undefined || v === null) return 0
  const raw = String(v)
  if (raw.indexOf('-') >= 0) return 0
  const s = raw.replace(/[^0-9.]/g, '')
  if (!s) return 0
  const n = Math.round(Number(s))
  return Number.isFinite(n) && n > 0 ? n : 0
}

// The same conversion for a SPREADSHEET cell, where the difference between "empty"
// and "not a number" has to be reported rather than silently turned into 0 — a CSV
// import that quietly reads "one lakh" as zero is worse than one that refuses.
// Returns null for a value that is not a number at all.
function boothRupeesStrict(v: any): number | null {
  const raw = String(v == null ? '' : v).trim().replace(/^(₹|rs\.?|inr)\s*/i, '')
  if (!raw) return 0
  const cleaned = raw.replace(/,/g, '')
  if (!/^[0-9]+(\.[0-9]+)?$/.test(cleaned)) return null
  const n = Math.round(Number(cleaned))
  return Number.isFinite(n) ? n : null
}

// A date out of a spreadsheet. Accepts ISO (what the date inputs send) and the
// dd/mm/yyyy Excel hands back on an Indian locale; returns null for blank and
// false — distinct from null — for something that is not a date.
function boothDate(v: any): string | null | false {
  const raw = String(v == null ? '' : v).trim()
  if (!raw) return null
  let m = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/)
  if (!m) {
    const d = raw.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/)
    if (d) m = [d[0], d[3], d[2], d[1]] as any
  }
  if (!m) return false
  const y = Number(m[1]), mo = Number(m[2]), day = Number(m[3])
  if (mo < 1 || mo > 12 || day < 1 || day > 31) return false
  return `${y}-${String(mo).padStart(2, '0')}-${String(day).padStart(2, '0')}`
}

// THE INVARIANT, in one place, because the record-a-sale form and the CSV import
// must not be able to disagree about it:
//     amount_inr      = list_price_inr - discount_inr
//     gst_inr         = round(amount_inr * 18 / 100)
//     grand_total_inr = amount_inr + gst_inr
// A typed net is never trusted — it is DERIVED here — so no route can write a row
// where the three numbers contradict each other.
//
// PRIVATE. Both write paths reach it through boothSaleMoneyChecked, which has
// already refused anything unusable, so what arrives here is clean integers and
// derivation is all that is left to do. Call that, not this.
function boothSaleMoney(input: any, fallbackList: number) {
  const given = input.list_price_inr !== undefined && input.list_price_inr !== null &&
    String(input.list_price_inr).trim() !== ''
  const list = given ? boothRupees(input.list_price_inr) : (Number(fallbackList) || 0)
  let discount = boothRupees(input.discount_inr)
  // This clamp used to be the WHOLE answer to a discount above the list price:
  // silently cap it and carry on, which returned a cheerful 201 on a Rs 0 sale —
  // the stand given away and the operator told it saved. That judgement has moved
  // to boothSaleMoneyChecked, which now refuses the figure by name before it can
  // reach here. What is left is the floor that keeps this arithmetic from ever
  // going negative if some future caller forgets the guard.
  if (discount > list) discount = list
  const amount = list - discount
  const gst = boothGst(amount)
  const grand = amount + gst
  const invoice = String(input.invoice_number || '').trim()
  let paid = boothRupees(input.amount_paid_inr)
  // TAX DEDUCTED AT SOURCE. An Indian B2B buyer withholds tax before paying — 2%
  // u/s 194C on a works contract, 10% u/s 194I where the stand reads as rent — and
  // pays it to the government against the seller's PAN. So amount_paid_inr on a
  // FULLY SETTLED stand legitimately never equals grand_total_inr, and every test
  // that compared those two directly reported a settled exhibitor as part_paid for
  // ever, chased them for money they had already handed to the Income Tax
  // Department, and understated Collected on the dashboard by the withheld amount.
  //
  // Settlement is therefore amount_paid_inr + tds_deducted_inr >= grand_total_inr,
  // in this one place, so no caller can go back to the two-number version.
  const tds = Math.min(grand, boothRupees(input.tds_deducted_inr))
  const settled = grand - tds
  let status = BOOTH_PAYMENT_STATUSES.includes(String(input.payment_status || ''))
    ? String(input.payment_status) : ''
  // Saying "paid" IS saying the whole invoice landed, so the receipts follow the
  // word rather than the operator having to type the grand total twice — less the
  // TDS, which is the part that will never arrive as cash.
  if (status === 'paid') paid = settled
  // Receipts above the invoice are a typo far more often than an overpayment, and
  // they would make outstanding (invoiced - collected) go negative on the
  // dashboard. Clamp, and let the operator correct the invoice if it was wrong.
  if (paid > settled) paid = settled
  // 'refunded' cannot be derived from the numbers, so it is the one status the
  // operator's choice always wins on. Everything else follows the money.
  if (status !== 'refunded' && status !== 'paid') {
    status = (paid + tds >= grand && grand > 0) ? 'paid'
      : (paid > 0 || tds > 0) ? 'part_paid'
      : invoice ? 'invoiced' : 'pending'
  }
  return {
    list_price_inr: list, discount_inr: discount, amount_inr: amount,
    gst_inr: gst, grand_total_inr: grand, amount_paid_inr: paid,
    tds_deducted_inr: tds,
    payment_status: status, invoice_number: invoice || null,
  }
}

// THE GUARD on that invariant, and the only door to boothSaleMoney. The CSV
// import and the record-a-sale form both ask this one function, so they cannot
// answer the same figures differently. They used to, and the disagreement cost
// real money:
//
//   * boothRupees dropped a leading minus, so PUT /api/admin/booths/:code/sale
//     with amount_paid_inr "-5000" returned 201 and banked +5000 as COLLECTED,
//     flipping the row to part_paid. Money never received inflated Collected and
//     shrank Outstanding on the dashboard, with no warning anywhere.
//   * a discount larger than the list price was CLAMPED, so 5,00,000 off a 38,000
//     stand saved a Rs 0 sale and reported success.
//
// The importer refused both by name all along. Now one function does, for both.
// Returns { error } — a sentence naming the field and quoting what it said, so the
// desk can act on it — or the derived money. A figure the operator did not type is
// never invented here: the answer to a bad number is a refusal, not a rewrite.
function boothSaleMoneyChecked(
  input: any, fallbackList: number
): { error: string } | ReturnType<typeof boothSaleMoney> {
  const cell = (v: any) => String(v === undefined || v === null ? '' : v).trim()

  // Blank means "leave the price alone" — the frozen list on an edit, the stand's
  // sticker on a new sale — which is the importer's rule for an empty cell too.
  const listRaw = cell(input.list_price_inr)
  const list = listRaw === '' ? Math.max(0, Math.round(Number(fallbackList) || 0)) : boothRupeesStrict(listRaw)
  if (list === null) return { error: `list_price_inr "${listRaw}" is not a number.` }

  const discountRaw = cell(input.discount_inr)
  const discount = boothRupeesStrict(discountRaw)
  if (discount === null) return { error: `discount_inr "${discountRaw}" is not a number.` }
  if (discount > list) return { error: `discount_inr (${discount}) is more than list_price_inr (${list}).` }

  const paidRaw = cell(input.amount_paid_inr)
  const paid = boothRupeesStrict(paidRaw)
  if (paid === null) return { error: `amount_paid_inr "${paidRaw}" is not a number.` }

  // The withholding gets the SAME door as the discount and the receipt, and for
  // the same reason: boothRupees would strip a leading minus and bank "-8,260" as
  // Rs 8,260 of tax the buyer never withheld, which would report an unpaid stand
  // as settled. A minus is a typo, and the answer to a typo is to name it.
  const tdsRaw = cell(input.tds_deducted_inr)
  const tds = boothRupeesStrict(tdsRaw)
  if (tds === null) return { error: `tds_deducted_inr "${tdsRaw}" is not a number.` }
  // TDS is withheld OUT OF the invoice, so it can never exceed it. At 10% u/s 194I
  // the real figure is a tenth of the net; anything near the grand total is a
  // misplaced decimal, and letting it through would mark the stand fully settled.
  const grandCheck = (list - discount) + boothGst(list - discount)
  if (tds > grandCheck) {
    return { error: `tds_deducted_inr (${tds}) is more than the grand total (${grandCheck}). TDS is withheld out of the invoice, not added to it.` }
  }

  return boothSaleMoney({
    ...input,
    list_price_inr: String(list), discount_inr: String(discount),
    amount_paid_inr: String(paid), tds_deducted_inr: String(tds),
  }, list)
}

// The one editable number on the sales dashboard. app_settings has existed since
// 0005 so this read is safe, but it is wrapped anyway: a target that cannot be
// read must fall back to the hall's full value, never break the dashboard.
async function boothRevenueTarget(c: any): Promise<number> {
  try {
    const row = await c.env.DB.prepare('SELECT value FROM app_settings WHERE key = ?')
      .bind(BOOTH_TARGET_KEY).first() as any
    const n = Math.round(Number(row?.value))
    if (Number.isFinite(n) && n >= 0) return n
  } catch { /* fall through to the seeded default */ }
  return BOOTH_TARGET_DEFAULT
}

// The two event days and the bookable hours inside them. Derived from the real
// schedule, not guessed: sessions (migration 0012, re-dated by 0013) run
// 08:30-17:10 on 20 Nov plus an 18:30-20:30 CXO cocktail, and 08:30-17:15 on
// 21 Nov. 09:00-18:00 therefore sits inside both days and clears the closing
// ceremony. Kept in code, not in a table, so trimming the window is a deploy
// rather than another --remote execute.
const ROOM_DAYS = ['2026-11-20', '2026-11-21']
const ROOM_SLOT_HOURS = ['09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00']
const ROOM_GST_PERCENT = 18
// Hours are the booking atom, so an end is always start + 1h. Text in, text out —
// no Date parsing, which would drag the worker's UTC into an IST venue schedule.
const roomSlotEnd = (start: string): string => {
  const h = parseInt(start.slice(11, 13), 10) + 1
  return start.slice(0, 11) + String(h).padStart(2, '0') + ':00'
}

// ==================== VERIFIED SIGN-IN ====================
//
// Sign-in used to be email-only: post an address, receive that account. This
// replaces it with a token emailed to the address, proving the caller controls it.
//
// Rollout switch: verified sign-in activates only once the login_tokens table
// exists (migration 0014). Until then the legacy path keeps working, so the code
// deploy and the migration are independent and can happen in either order.
let _loginTokensTable: boolean | null = null
async function verifiedLoginEnabled(c: any): Promise<boolean> {
  if (_loginTokensTable !== null) return _loginTokensTable
  try {
    const row = await c.env.DB.prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name='login_tokens'"
    ).first()
    _loginTokensTable = !!row
  } catch { _loginTokensTable = false }
  return _loginTokensTable
}

const sha256Hex = async (v: string): Promise<string> => {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(v))
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('')
}

const randomHex = (bytes: number): string => {
  const a = new Uint8Array(bytes)
  crypto.getRandomValues(a)
  return Array.from(a).map(b => b.toString(16).padStart(2, '0')).join('')
}

// Six digits from a CSPRNG, uniformly distributed (no modulo bias).
const randomCode = (): string => {
  const a = new Uint32Array(1)
  let v: number
  do { crypto.getRandomValues(a); v = a[0] } while (v >= 4294000000)
  return String(v % 1000000).padStart(6, '0')
}

// Sent whether or not the address is registered — see send-magic-link.
const NEUTRAL_SIGNIN_REPLY = 'If that email is registered, a sign-in link and code are on their way.'
const LOGIN_RATE_WINDOW_MIN = 15
const LOGIN_RATE_MAX = 4
const LOGIN_TOKEN_MINUTES = 15
const LOGIN_MAX_ATTEMPTS = 5

// Issues a single-use token + code for an email, storing only their hashes.
// Returns null when the address has asked too often; the caller still replies
// neutrally so this cannot be used to probe which addresses exist.
async function loginTokenRateLimited(c: any, eventId: any, email: string): Promise<boolean> {
  const row = await c.env.DB.prepare(
    `SELECT COUNT(*) AS n FROM login_tokens
      WHERE event_id = ? AND email = ? AND created_at > datetime('now', '-${LOGIN_RATE_WINDOW_MIN} minutes')`
  ).bind(eventId, email).first() as any
  return (row?.n || 0) >= LOGIN_RATE_MAX
}

// ttlMinutes is a parameter because a campaign email is not a sign-in link. Fifteen
// minutes is right when someone is sitting at the login screen waiting for a code;
// it is useless for a mail sent to a thousand people who will open it that evening,
// or on Monday. Callers that do not pass one keep the short default.
async function createLoginToken(c: any, eventId: any, email: string, ttlMinutes: number = LOGIN_TOKEN_MINUTES) {
  // Nothing else prunes this table and every sign-in adds a row. Clearing spent and
  // expired rows here keeps it from growing without bound, with no cron needed.
  await c.env.DB.prepare(
    "DELETE FROM login_tokens WHERE expires_at < datetime('now', '-1 day') OR (used_at IS NOT NULL AND used_at < datetime('now', '-1 day'))"
  ).run()

  const token = randomHex(32)
  const code = randomCode()
  // Supersede anything outstanding for this address so an old code cannot be reused.
  await c.env.DB.prepare(
    "UPDATE login_tokens SET used_at = datetime('now') WHERE event_id = ? AND email = ? AND used_at IS NULL"
  ).bind(eventId, email).run()
  await c.env.DB.prepare(
    `INSERT INTO login_tokens (event_id, email, token_hash, code_hash, expires_at)
     VALUES (?, ?, ?, ?, datetime('now', '+${Math.max(1, Math.round(ttlMinutes))} minutes'))`
  ).bind(eventId, email, await sha256Hex(token), await sha256Hex(code)).run()
  return { token, code }
}

// Redeems a token or code. Returns the email on success, or a reason string.
async function redeemLoginToken(c: any, eventId: any, email: string, token?: string, code?: string):
    Promise<{ ok: true } | { ok: false; reason: string }> {
  const row = await c.env.DB.prepare(
    `SELECT id, token_hash, code_hash, attempts FROM login_tokens
     WHERE event_id = ? AND email = ? AND used_at IS NULL AND expires_at > datetime('now')
     ORDER BY id DESC LIMIT 1`
  ).bind(eventId, email).first() as any
  if (!row) return { ok: false, reason: 'That link or code has expired. Please request a new one.' }
  if (row.attempts >= LOGIN_MAX_ATTEMPTS) {
    await c.env.DB.prepare("UPDATE login_tokens SET used_at = datetime('now') WHERE id = ?").bind(row.id).run()
    return { ok: false, reason: 'Too many attempts. Please request a new code.' }
  }
  const supplied = token ? await sha256Hex(token) : code ? await sha256Hex(code) : ''
  const expected = token ? row.token_hash : row.code_hash
  if (!supplied || !safeEqualA(supplied, expected)) {
    await c.env.DB.prepare('UPDATE login_tokens SET attempts = attempts + 1 WHERE id = ?').bind(row.id).run()
    return { ok: false, reason: 'That code is not correct.' }
  }
  await c.env.DB.prepare("UPDATE login_tokens SET used_at = datetime('now') WHERE id = ?").bind(row.id).run()
  return { ok: true }
}

// ==================== ATTENDEE SESSIONS ====================
//
// Why this exists: every write that names a person used to take that person's id
// straight from the URL or the request body and trust it. Since attendee ids are
// published in the public directory, anyone could edit any profile or post a
// message as anyone — no email, no password, no knowledge of the victim at all.
//
// The cookie is `<id>.<exp>.<hmac>`, signed with the server secret, so an edited
// id fails verification. Deliberately stateless: the only binding on this project
// is D1, and a sessions table would need a migration applied by hand against the
// production database. A signed token needs no storage.
//
// Mirrors the marketplace implementation (src/routes/marketplace.ts) rather than
// inventing a second scheme, including its ADMIN_SECRET fallback — so protection
// is active immediately, without waiting for a new secret to be provisioned.
// Set a dedicated one when convenient: `npx wrangler pages secret put SESSION_SECRET`.
const attendeeSessionSecret = (c: any): string =>
  c.env.SESSION_SECRET || c.env.ADMIN_SECRET || ''

const hmacHexA = async (secret: string, message: string): Promise<string> => {
  const enc = new TextEncoder()
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(message))
  return Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join('')
}

const safeEqualA = (a: string, b: string): boolean => {
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return diff === 0
}

const ATTENDEE_SESSION_DAYS = 60

async function signAttendeeSession(c: any, attendeeId: number | string): Promise<string> {
  const secret = attendeeSessionSecret(c)
  const exp = Math.floor(Date.now() / 1000) + ATTENDEE_SESSION_DAYS * 86400
  const body = `${attendeeId}.${exp}`
  return `${body}.${await hmacHexA(secret, body)}`
}

// Returns the verified attendee id from the cookie, or null.
async function verifyAttendeeSession(c: any): Promise<number | null> {
  const secret = attendeeSessionSecret(c)
  if (!secret) return null
  const raw = (c.req.header('Cookie') || '')
    .split(';').map((s: string) => s.trim())
    .find((s: string) => s.startsWith('bai_session='))
  if (!raw) return null
  const value = decodeURIComponent(raw.slice('bai_session='.length))
  const parts = value.split('.')
  if (parts.length !== 3) return null
  const [id, exp, sig] = parts
  if (!/^\d+$/.test(id) || !/^\d+$/.test(exp)) return null
  if (parseInt(exp, 10) * 1000 < Date.now()) return null
  const expected = await hmacHexA(secret, `${id}.${exp}`)
  if (!safeEqualA(sig, expected)) return null
  return parseInt(id, 10)
}

const attendeeSessionCookie = (value: string) =>
  `bai_session=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${ATTENDEE_SESSION_DAYS * 86400}`

// Attaches a fresh session cookie to the response. Called from every route that
// establishes who the caller is (register / signin / login), so existing users
// pick one up on their next visit without touching the client.
async function issueAttendeeSession(c: any, attendeeId: number | string) {
  if (!attendeeSessionSecret(c)) return
  c.header('Set-Cookie', attendeeSessionCookie(await signAttendeeSession(c, attendeeId)))
}

// Guard for writes that act on a specific attendee. Returns a Response to send
// back (blocking the write), or null to proceed.
//
// Fails OPEN when no secret is configured, so a missing/rotated secret degrades
// to today's behaviour instead of locking 852 people out of their own profiles.
// GET /api/auth/status reports which mode is live.
async function requireSelf(c: any, targetId: any): Promise<Response | null> {
  if (!attendeeSessionSecret(c)) return null
  if (isAdminRequest(c)) return null
  const me = await verifyAttendeeSession(c)
  if (!me) return c.json({ error: 'Please sign in again to continue.' }, 401)
  if (String(me) !== String(targetId)) return c.json({ error: 'You can only change your own details.' }, 403)
  return null
}

// Lets us confirm from outside whether enforcement is on, without exposing the
// secret itself.
app.get('/api/auth/status', async (c) => {
  return c.json({
    enforced: !!attendeeSessionSecret(c),
    session_valid: (await verifyAttendeeSession(c)) !== null,
  })
})

app.get('/api/events/:id/attendees', async (c) => {
  const eventId = c.req.param('id')
  const search = c.req.query('search')
  const role = c.req.query('role')
  const interest = c.req.query('interest')

  // Named columns rather than *, and intersected with what the table actually
  // holds, so a database still short of migration 0015/0018/0023 answers with the
  // columns it has instead of failing the whole request on "no such column".
  let cols = ATTENDEE_PUBLIC_COLS
  if (isAdminRequest(c)) {
    const have = await attendeeColumns(c)
    const picked = ATTENDEE_ADMIN_LIST_COLS.filter(f => have.has(f))
    cols = (picked.length ? picked : ['id', 'name', 'email']).join(', ')
  }

  // The WHERE is built once and reused by the count below, so the two can't drift.
  let where = ' WHERE event_id = ?'
  const params: any[] = [eventId]

  if (search) {
    where += ' AND (name LIKE ? OR company LIKE ? OR job_title LIKE ?)'
    const s = `%${search}%`
    params.push(s, s, s)
  }
  if (role) {
    where += ' AND role LIKE ?'
    params.push(`%${role}%`)
  }
  if (interest) {
    where += ' AND interests LIKE ?'
    params.push(`%${interest}%`)
  }

  // Everyone who is not an admin gets a page, never the whole directory.
  if (!isAdminRequest(c)) {
    const size = Math.min(PUBLIC_PAGE_MAX, Math.max(1,
      parseInt(c.req.query('limit') || '', 10) || PUBLIC_PAGE_DEFAULT))
    const cur = decodeAttendeeCursor(c.req.query('cursor'))
    let pw = where
    const pp = [...params]
    if (cur) {
      pw += ' AND (name > ? OR (name = ? AND id > ?))'
      pp.push(cur.name, cur.name, cur.id)
    }
    // Fetch one more row than asked for. That single extra row answers "is there
    // another page?" without a COUNT - which matters, because a COUNT here is the
    // registration count, and not running it is the point.
    const got = ((await c.env.DB.prepare(
      `SELECT ${cols} FROM attendees${pw} ORDER BY name ASC, id ASC LIMIT ${size + 1}`
    ).bind(...pp).all()).results || []) as any[]
    const more = got.length > size
    const pageRows = more ? got.slice(0, size) : got
    const last = pageRows[pageRows.length - 1]
    return new Response(JSON.stringify(pageRows), {
      headers: {
        'Content-Type': 'application/json; charset=UTF-8',
        'X-Returned-Count': String(pageRows.length),
        // Present only while more remain. Its absence is how the client knows to
        // stop, and it says nothing about how many are left.
        'X-Next-Cursor': more && last ? encodeAttendeeCursor(last.name, last.id) : '',
        'X-Has-More': more ? '1' : '0',
        'Access-Control-Expose-Headers': 'X-Returned-Count, X-Next-Cursor, X-Has-More',
      },
    })
  }

  const limit = attendeeListLimit(c.req.query('limit'))
  const query = `SELECT ${cols} FROM attendees${where} ORDER BY is_online DESC, name ASC LIMIT ${limit}`

  const { results } = await c.env.DB.prepare(query).bind(...params).all()
  let rows = (results || []) as any[]
  const fetched = rows.length

  // A row cap is only a guess at a size, because rows vary. THIS is the guarantee:
  // serialise, measure, and drop rows until the body is small enough to deliver.
  // Crossing the limit does not truncate the response, it replaces the body with
  // something that is not JSON at all - which is the whole outage. Nothing here
  // gets to assume a response is small enough; it gets measured.
  const enc = new TextEncoder()
  let body = JSON.stringify(rows)
  let bytes = enc.encode(body).length
  while (bytes > ATTENDEE_LIST_MAX_BYTES && rows.length > 1) {
    // Scale by how far over we are, with a little margin so this converges in one
    // or two passes rather than creeping down a row at a time.
    const keep = Math.max(1, Math.floor(rows.length * (ATTENDEE_LIST_MAX_BYTES / bytes) * 0.95))
    if (keep >= rows.length) break
    rows = rows.slice(0, keep)
    body = JSON.stringify(rows)
    bytes = enc.encode(body).length
  }

  // The grid shows "N total" and offers to fetch the rest, so it needs the true
  // count - but only when something was actually left out. In the normal case the
  // rows in hand are the count, and the extra query is not run at all.
  let total = rows.length
  if (rows.length < fetched || fetched >= limit) {
    try {
      const row = await c.env.DB.prepare(`SELECT COUNT(*) AS n FROM attendees${where}`).bind(...params).first() as any
      const n = Number(row && row.n)
      if (Number.isFinite(n) && n > total) total = n
    } catch { /* the count is a nicety; the rows already fetched are the answer */ }
  }

  // Which ceiling bit matters to the caller: a row cap can be lifted with ?limit=,
  // a byte cap cannot - past it there is no larger response to ask for, only the
  // CSV export. Saying which one stops the UI offering a button that cannot work.
  const cut = total > rows.length
  const cutBy = !cut ? '' : (rows.length < fetched ? 'bytes' : 'rows')

  // The body stays exactly what it has always been - a bare array - so every
  // existing caller is untouched. The counts ride along in headers. Built by hand
  // rather than with c.json() only so the string measured above is the string sent.
  return new Response(body, {
    headers: {
      'Content-Type': 'application/json; charset=UTF-8',
      // Only admins reach this far - every other caller was served a page above,
      // with no total in it at all. The admin table pages on this header and is
      // the one place meant to see the whole room, so it is sent as it always was.
      'X-Total-Count': String(total),
      'X-Returned-Count': String(rows.length),
      'X-Truncated': cut ? '1' : '0',
      'X-Truncated-By': cutBy,
      'Access-Control-Expose-Headers': 'X-Total-Count, X-Returned-Count, X-Truncated, X-Truncated-By',
    },
  })
})

// The "Recommended for you" rail used to rank the whole directory in the browser,
// which only worked because the browser had the whole directory. It no longer
// does, so the candidates come from here: everyone who shares at least one stated
// interest with the caller, capped well below any useful headcount, topped up with
// other attendees when the caller's interests match too few people.
//
// The ranking itself deliberately stays in the client, where the seniority table
// already lives - duplicating that here would give us two copies to keep in step.
const SUGGEST_POOL = 60
app.get('/api/events/:id/suggested-attendees', async (c) => {
  const eventId = c.req.param('id')
  const me = await verifyAttendeeSession(c)
  if (!me && attendeeSessionSecret(c)) return c.json([])

  const mine = await c.env.DB.prepare('SELECT interests FROM attendees WHERE id = ?')
    .bind(me).first() as any
  const terms = String(mine?.interests || '')
    .split(',').map((t: string) => t.trim()).filter(Boolean).slice(0, 6)

  const out: any[] = []
  const seen = new Set<number>([Number(me)])

  if (terms.length) {
    const ors = terms.map(() => 'interests LIKE ?').join(' OR ')
    const rows = ((await c.env.DB.prepare(
      `SELECT ${ATTENDEE_PUBLIC_COLS} FROM attendees WHERE event_id = ? AND id <> ? AND (${ors}) LIMIT ${SUGGEST_POOL}`
    ).bind(eventId, me, ...terms.map((t: string) => '%' + t + '%')).all()).results || []) as any[]
    for (const r of rows) { if (!seen.has(r.id)) { seen.add(r.id); out.push(r) } }
  }

  if (out.length < SUGGEST_POOL) {
    const rows = ((await c.env.DB.prepare(
      `SELECT ${ATTENDEE_PUBLIC_COLS} FROM attendees WHERE event_id = ? AND id <> ? ORDER BY id DESC LIMIT ${SUGGEST_POOL}`
    ).bind(eventId, me).all()).results || []) as any[]
    for (const r of rows) {
      if (out.length >= SUGGEST_POOL) break
      if (!seen.has(r.id)) { seen.add(r.id); out.push(r) }
    }
  }

  return c.json(out)
})

app.get('/api/attendees/:id', async (c) => {
  const id = c.req.param('id')
  const cols = isAdminRequest(c) ? '*' : ATTENDEE_PUBLIC_COLS
  const attendee = await c.env.DB.prepare(`SELECT ${cols} FROM attendees WHERE id = ?`).bind(id).first()
  if (!attendee) return c.json({ error: 'Attendee not found' }, 404)
  return c.json(attendee)
})

// Where a registration came from. Until now neither registration endpoint wrote the
// column: /api/events/:id/attendees/register omitted it entirely, so rows fell back
// to the 0007 default 'networking_app', and /api/external/register bound the literal
// 'website'. Either way a registration driven by a campus panel was indistinguishable
// from one off the home page, so there was no way to tell a host institution or a
// sponsor what their panel actually produced.
//
// Both endpoints are unauthenticated, so the value is shape-checked rather than
// trusted: lowercase, bounded length, and only the characters our own tags use.
// Anything else returns null and the caller falls back to its previous default, so a
// junk or injected value can never reach a report. Campus tags are written as
// 'campus:<panel-slug>' — campus:djsanghvi-21sep, campus:jnu-30sep — and the export
// sweeper keys off that prefix.
const REGISTRATION_SOURCE_RE = /^[a-z0-9][a-z0-9:_-]{0,39}$/
function sanitizeRegistrationSource(value: unknown): string | null {
  const raw = String(value ?? '').trim().toLowerCase()
  return REGISTRATION_SOURCE_RE.test(raw) ? raw : null
}

app.post('/api/events/:id/attendees/register', async (c) => {
  const eventId = c.req.param('id')
  const body = await c.req.json()
  const { name, email, company, job_title, bio, interests, linkedin_url, mobile, lunch_inclusion, city, badge_type, registration_source } = body

  if (!name || !email) return c.json({ error: 'Name and email are required' }, 400)

  const normalizedEmail = email.trim().toLowerCase()

  // Mobile, organisation, designation and city are required, not optional extras.
  // Most existing rows carry dashes in those columns, which makes the attendee list
  // unusable for calling people, printing a badge, or knowing who is in the room.
  // The forms mark them too; this is the check that holds, because a form can be
  // bypassed.
  //
  // Only when a record is being CREATED. A returning app re-posts this endpoint on
  // load to mark itself online, carrying just the few fields it kept in
  // localStorage — demanding the full set there would 400 that refresh and sign
  // every returning user out.
  const known = await c.env.DB.prepare('SELECT id FROM attendees WHERE event_id = ? AND email = ?')
    .bind(eventId, normalizedEmail).first()
  if (!known) {
    const missing = missingRegistrationFields(body)
    if (missing.length) {
      return c.json({ error: 'Please add your ' + humanList(missing) + '.', missing }, 400)
    }
  }

  // Honor the pass the user selected. Previously this hardcoded 'Visitor Pass',
  // so anyone who chose (and paid for) Delegate/VIP/Academic was stored as a
  // free Visitor and then locked out of networking. Validate against a known
  // allowlist so a bad value can't create an arbitrary pass; default to Visitor.
  const industryValue = INDUSTRIES.includes(String(body.industry || '')) ? String(body.industry) : ''
  const ALLOWED_PASSES = ['Visitor Pass', 'Delegate Pass', 'VIP Pass', 'Academic Pass', 'Media Pass']
  const passType = ALLOWED_PASSES.includes(badge_type) ? badge_type : 'Visitor Pass'

  const sourceValue = sanitizeRegistrationSource(registration_source)

  // A paid tier chosen at registration is recorded but marked unpaid; payment is
  // confirmed out of band on mUni Campus, so it cannot be trusted from the client.
  const needsPayment = PAID_TIERS.includes(passType)
  const withPaymentCol = await paymentStatusEnabled(c)

  try {
    const result = withPaymentCol
      ? await c.env.DB.prepare(
          // registration_date is written here rather than left to a default: the column
          // was added later, so it has none, and every row that skipped it sorted to
          // the bottom of a newest-first list - exactly the rows you most want to see.
          'INSERT INTO attendees (event_id, name, email, company, job_title, bio, interests, linkedin_url, mobile, city, industry, lunch_inclusion, badge_type, payment_status, registration_source, registration_date, is_online, last_login_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime("now"), 1, datetime("now"))'
        ).bind(eventId, name.trim(), normalizedEmail, company || '', job_title || '', bio || '', interests || '', linkedin_url || '', mobile || '', city || '', industryValue, lunch_inclusion || 'No', passType, needsPayment ? 'pending' : 'paid', sourceValue || 'networking_app').run()
      : await c.env.DB.prepare(
          'INSERT INTO attendees (event_id, name, email, company, job_title, bio, interests, linkedin_url, mobile, city, industry, lunch_inclusion, badge_type, registration_source, registration_date, is_online, last_login_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime("now"), 1, datetime("now"))'
        ).bind(eventId, name.trim(), normalizedEmail, company || '', job_title || '', bio || '', interests || '', linkedin_url || '', mobile || '', city || '', industryValue, lunch_inclusion || 'No', passType, sourceValue || 'networking_app').run()

    const attendee = await c.env.DB.prepare('SELECT * FROM attendees WHERE id = ?').bind(result.meta.last_row_id).first()
    await issueAttendeeSession(c, (attendee as any).id)

    // A campus-panel registrant gets the panel's joining details; everyone else gets
    // the conference welcome exactly as before. An unknown campus slug also falls
    // back to the welcome rather than sending nothing.
    //
    // c.executionCtx throws when absent rather than being undefined, so this is
    // guarded rather than optional-chained.
    const panel = campusPanelFor((attendee as any).registration_source)
    const welcome = panel ? sendPanelConfirmationEmail(c, attendee, panel) : sendRegistrationEmail(c, attendee)
    let scheduled = false
    try { c.executionCtx.waitUntil(welcome); scheduled = true } catch { /* no ctx */ }
    if (!scheduled) await welcome

    return c.json(attendee, 201)
  } catch (e: any) {
    if (e.message?.includes('UNIQUE')) {
      const existing = await c.env.DB.prepare('SELECT * FROM attendees WHERE event_id = ? AND email = ?').bind(eventId, normalizedEmail).first()
      if (existing) {
        // Registering with an address that already exists must NOT hand back that
        // account — that made /register a second email-only login. A caller holding
        // a valid session for this account (the app re-registers on load to mark
        // itself online) is refreshed as before; anyone else is sent to verification.
        const me = await verifyAttendeeSession(c)
        const isOwner = me !== null && String(me) === String((existing as any).id)
        if (!isOwner && await verifiedLoginEnabled(c)) {
          return c.json({ error: 'verification_required', message: 'That email is already registered. Please sign in with the link or code we email you.' }, 403)
        }
        await c.env.DB.prepare('UPDATE attendees SET is_online = 1, last_login_at = datetime("now") WHERE id = ?').bind((existing as any).id).run()
        await issueAttendeeSession(c, (existing as any).id)
        return c.json(existing)
      }
    }
    // Until now this swallowed the cause. A visitor reported "Registration failed"
    // and there was nothing anywhere - no log, no audit row - to say what the
    // database or the session signer had actually objected to. The row is written
    // to the same admin_audit table the external route uses for its rejections, so
    // the next report can be answered from the panel instead of guessed at.
    console.error('attendee register failed', normalizedEmail, e?.message)
    await audit(c, 'register.failed', 'attendee', null,
      { email: normalizedEmail, error: String(e?.message || e).slice(0, 500), badge_type: passType, source: sourceValue || 'networking_app' },
      { actor: 'public registration', kind: 'public' })
    return c.json({ error: 'Registration failed' }, 400)
  }
})

// A student has no employer and no job title, so the Academic tier collapses both
// into a single College Name - asking that tier for a designation is asking a
// question with no answer.
// A fixed list, not free text. Sponsors are shown a breakdown by sector, and free
// text turns that into forty spellings of "IT" that no chart can add up.
const INDUSTRIES = [
  'Banking & Financial Services',
  'Insurance',
  'IT Services & Consulting',
  'Software & SaaS',
  'Telecom',
  'Manufacturing',
  'Automotive',
  'Pharma & Life Sciences',
  'Healthcare & Hospitals',
  'Retail & E-commerce',
  'Logistics & Supply Chain',
  'Energy & Utilities',
  'Media & Entertainment',
  'Education & Academia',
  'Government & Public Sector',
  'Consulting & Professional Services',
  'Startup / Early stage',
  'Venture Capital & Investment',
  'Agriculture & Agritech',
  'Real Estate & Construction',
  'Aerospace & Defence',
  'Other',
]

function missingRegistrationFields(b: any): string[] {
  const has = (v: any) => String(v ?? '').trim().length > 0
  const academic = String(b.badge_type || '') === 'Academic Pass'
  const missing: string[] = []
  if (!has(b.mobile)) missing.push('mobile number')
  if (!has(b.company)) missing.push(academic ? 'college name' : 'organisation')
  if (!academic && !has(b.job_title)) missing.push('designation')
  if (!has(b.city)) missing.push('city')
  if (!has(b.industry)) missing.push('industry')
  return missing
}

const humanList = (xs: string[]): string =>
  xs.length < 2 ? (xs[0] || '') : xs.slice(0, -1).join(', ') + ' and ' + xs[xs.length - 1]

// ==================== EXTERNAL REGISTRATION (from bharataiinnovation.com) ====================

// Maps pass types from main site to badge_type in DB
const PASS_TYPE_MAP: Record<string, string> = {
  'delegate': 'Delegate Pass',
  'vip': 'VIP Pass',
  'startup': 'Visitor Pass',
  'academic': 'Academic Pass',
  'visitor': 'Visitor Pass',
  'media': 'Media Pass',
}

app.post('/api/external/register', async (c) => {
  const body = await c.req.json()
  const {
    first_name, last_name, email, phone, organization, job_title,
    industry, company_size, city, country, source, special_requirements,
    package: passPackage, newsletter
  } = body

  if (!first_name || !email) return c.json({ error: 'Name and email are required' }, 400)

  const fullName = `${first_name.trim()} ${(last_name || '').trim()}`.trim()
  const normalizedEmail = email.trim().toLowerCase()
  const badgeType = PASS_TYPE_MAP[passPackage] || 'Visitor Pass'
  const eventId = 1

  // The same required fields as the in-app form: a pass is printed from this
  // record, so a registration without a mobile, organisation, designation, city
  // and industry only creates work later. The photo is the exception - it is
  // asked for at pass download, not here.
  //
  // This route used to skip the check because an unidentified caller posts to it.
  // It has taken one registration in six months and nothing since 5 March, so the
  // caller is dormant; and a rejection is now written to the audit log, so if a
  // real integration does start failing it is visible in the panel rather than
  // silent.
  const missing = missingRegistrationFields({
    mobile: phone, company: organization, job_title, city, industry, badge_type: badgeType,
  })
  if (missing.length) {
    await audit(c, 'external-register.rejected', 'attendee', null,
      { email: normalizedEmail, missing, source: sanitizeRegistrationSource(source) || 'website' },
      { actor: 'external registration caller', kind: 'public' })
    return c.json({
      error: `Please provide ${humanList(missing)}.`,
      missing,
    }, 400)
  }

  try {
    // Try to add all the extra columns — if migration hasn't run yet, the basic columns still work
    const result = await c.env.DB.prepare(
      `INSERT INTO attendees (
        event_id, name, email, company, job_title, mobile, badge_type,
        lunch_inclusion, is_online, last_login_at,
        industry, city, country, company_size, special_requirements,
        registration_source, pass_type
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, datetime("now"), ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      eventId, fullName, normalizedEmail,
      organization || '', job_title || '', phone || '', badgeType,
      badgeType === 'Visitor Pass' ? 'No' : 'Yes',
      industry || '', city || '', country || 'India',
      company_size || '', special_requirements || '',
      sanitizeRegistrationSource(source) || 'website', passPackage || 'visitor'
    ).run()

    const attendee = await c.env.DB.prepare('SELECT * FROM attendees WHERE id = ?').bind(result.meta.last_row_id).first() as any

    const refId = 'BHAI-2026-' + String(attendee.id).padStart(5, '0')
    return c.json({
      success: true,
      reference: refId,
      attendee_id: attendee.id,
      name: attendee.name,
      email: attendee.email,
      badge_type: attendee.badge_type,
      networking_app_url: `https://bharatai-networking.pages.dev?email=${encodeURIComponent(attendee.email)}`
    }, 201)
  } catch (e: any) {
    if (e.message?.includes('UNIQUE')) {
      // Already registered — return existing
      const existing = await c.env.DB.prepare(
        'SELECT * FROM attendees WHERE event_id = ? AND email = ?'
      ).bind(eventId, normalizedEmail).first() as any

      if (existing) {
        // NO LONGER upgrades badge_type. This endpoint is unauthenticated, so the
        // old UPDATE let anyone raise any attendee's pass tier — their own or a
        // stranger's — to VIP by posting that person's email with package=vip.
        // Entitlements are only changed by an admin (PATCH /api/admin/attendees/:id)
        // once payment is confirmed. Re-registering still just marks them online.
        await c.env.DB.prepare(
          'UPDATE attendees SET last_login_at = datetime("now") WHERE id = ?'
        ).bind(existing.id).run()
        const refId = 'BHAI-2026-' + String(existing.id).padStart(5, '0')
        return c.json({
          success: true,
          reference: refId,
          attendee_id: existing.id,
          name: existing.name,
          email: existing.email,
          badge_type: existing.badge_type,
          networking_app_url: `https://bharatai-networking.pages.dev?email=${encodeURIComponent(existing.email)}`,
          already_registered: true
        })
      }
    }
    return c.json({ error: 'Registration failed', details: e.message }, 400)
  }
})

// ==================== ATTENDEE EXPORT (AImailPilot sync) ====================
//
// Read-only endpoint consumed by AImailPilot's bharatai-attendee-sync
// sweeper (https://github.com/aimailpilot/aimailpilot, runs every 4h).
// Returns attendees as a JSON array sorted by created_at ASC so the
// downstream watermark advances monotonically.
//
// Auth: bearer token in Authorization header. Secret is a Cloudflare
// Workers env var (set via `wrangler secret put ATTENDEE_EXPORT_SECRET`),
// not in the repo or DB. Same value is pasted into AImailPilot Advanced
// Settings as a write-only field.
//
// Query params:
//   event_id (default 1)  — the conference instance
//   since    (optional)   — ISO timestamp; only return rows with
//                           created_at >= since (delta sync)
//   limit    (default 5000, max 5000)
app.get('/api/external/attendees-export', async (c) => {
  const authHeader = c.req.header('Authorization') || ''
  const expected = c.env.ATTENDEE_EXPORT_SECRET || ''
  if (!expected) {
    return c.json({ error: 'export endpoint not configured' }, 500)
  }
  if (authHeader !== `Bearer ${expected}`) {
    return c.json({ error: 'unauthorized' }, 401)
  }

  const eventIdRaw = c.req.query('event_id') || '1'
  const eventId = parseInt(eventIdRaw, 10)
  if (!Number.isFinite(eventId) || eventId <= 0) {
    return c.json({ error: 'invalid event_id' }, 400)
  }
  const since = (c.req.query('since') || '').trim()
  const limitRaw = parseInt(c.req.query('limit') || '5000', 10)
  const limit = Math.min(Math.max(limitRaw || 5000, 1), 5000)

  let sql = `SELECT id, event_id, name, email, company, job_title, bio,
                    avatar_url, interests, linkedin_url, twitter_url,
                    website_url, role, badge_type, industry, city, country,
                    company_size, pass_type, registration_source, created_at
               FROM attendees
              WHERE event_id = ?`
  const args: any[] = [eventId]
  if (since) {
    sql += ` AND created_at >= ?`
    args.push(since)
  }

  // The sweeper feeds a sequence that sells Delegate and VIP passes. Campus-panel
  // registrations are students who came to a free session on their own campus, so
  // dropping them into that sequence is both the wrong message and a way to make
  // the paid-conversion rate look worse than it is. Excluded by default;
  // ?include_campus=1 opts back in once a student-appropriate sequence exists.
  //
  // No row carries a campus: tag yet — the writes that create them ship alongside
  // this — so today the clause matches everything and the sweeper sees no change.
  if (c.req.query('include_campus') !== '1') {
    sql += ` AND (registration_source IS NULL OR registration_source NOT LIKE 'campus:%')`
  }

  sql += ` ORDER BY created_at ASC LIMIT ?`
  args.push(limit)

  const result = await c.env.DB.prepare(sql).bind(...args).all()
  return c.json(result.results || [])
})

// ==================== SIGN IN API ====================

app.post('/api/events/:id/attendees/signin', async (c) => {
  const eventId = c.req.param('id')
  const { email } = await c.req.json()

  if (!email) return c.json({ error: 'Email is required' }, 400)

  // Once migration 0014 is applied, an email address stops being a credential.
  // The client is told to switch to the emailed link/code flow.
  if (await verifiedLoginEnabled(c)) {
    return c.json({ error: 'verification_required', message: 'Please use the sign-in link or code we email you.' }, 403)
  }

  const attendee = await c.env.DB.prepare(
    'SELECT * FROM attendees WHERE event_id = ? AND email = ?'
  ).bind(eventId, email.trim().toLowerCase()).first()

  if (!attendee) {
    return c.json({ error: 'No account found with this email. Please register first.' }, 404)
  }

  // Mark user as online and track login time
  await c.env.DB.prepare('UPDATE attendees SET is_online = 1, last_login_at = datetime("now") WHERE id = ?').bind((attendee as any).id).run()
  await issueAttendeeSession(c, (attendee as any).id)

  return c.json(attendee)
})

// Login endpoint (alias for signin — used by auto-login from email links)
app.post('/api/events/:id/attendees/login', async (c) => {
  const eventId = c.req.param('id')
  const { email, token, code } = await c.req.json()
  if (!email) return c.json({ error: 'Email is required' }, 400)

  // Verified path: a link token or a 6-digit code must accompany the address.
  if (await verifiedLoginEnabled(c)) {
    if (!token && !code) {
      return c.json({ error: 'verification_required', message: 'Please use the sign-in link or code we email you.' }, 403)
    }
    const redeemed = await redeemLoginToken(c, eventId, String(email).trim().toLowerCase(), token, code)
    if (!redeemed.ok) return c.json({ error: redeemed.reason }, 401)
  }
  const attendee = await c.env.DB.prepare(
    'SELECT * FROM attendees WHERE event_id = ? AND email = ?'
  ).bind(eventId, email.trim().toLowerCase()).first()
  if (!attendee) return c.json({ error: 'No account found with this email.' }, 404)
  await c.env.DB.prepare('UPDATE attendees SET is_online = 1, last_login_at = datetime("now") WHERE id = ?').bind((attendee as any).id).run()
  await issueAttendeeSession(c, (attendee as any).id)
  return c.json(attendee)
})

// ==================== MAGIC LINK LOGIN ====================
app.post('/api/events/:id/attendees/send-magic-link', async (c) => {
  const eventId = c.req.param('id')
  const { email } = await c.req.json()
  if (!email) return c.json({ error: 'Email is required' }, 400)
  const normalizedEmail = email.trim().toLowerCase()

  // Check if attendee exists
  const attendee = await c.env.DB.prepare(
    'SELECT * FROM attendees WHERE event_id = ? AND email = ?'
  ).bind(eventId, normalizedEmail).first() as any

  if (!attendee) {
    // Neutral response: replying 404 here confirmed which addresses are registered,
    // letting anyone test a list of emails against the delegate database. The
    // wording MUST stay byte-identical to the success case below, or the two
    // replies distinguish a registered address just as plainly as a 404 did.
    return c.json({ success: true, message: NEUTRAL_SIGNIN_REPLY })
  }

  // Build magic link URL
  const appUrlRow = await c.env.DB.prepare("SELECT value FROM app_settings WHERE key = 'app_url'").first() as any
  const appUrl = appUrlRow?.value || 'https://bharataiinnovation.com/app'
  // Was `?email=<address>&action=magic-login` — no token at all, so anyone could
  // construct the "magic link" for any address without receiving the mail. It now
  // carries a single-use token that expires in 15 minutes.
  let loginCode = ''
  let magicLink = `${appUrl}?email=${encodeURIComponent(normalizedEmail)}&action=magic-login`
  if (await verifiedLoginEnabled(c)) {
    // Same neutral reply as an unknown address — refusing loudly would confirm the
    // address exists, and would also tell an abuser their flooding is working.
    if (await loginTokenRateLimited(c, eventId, normalizedEmail)) {
      return c.json({ success: true, message: NEUTRAL_SIGNIN_REPLY })
    }
    const issued = await createLoginToken(c, eventId, normalizedEmail)
    loginCode = issued.code
    magicLink = `${appUrl}?email=${encodeURIComponent(normalizedEmail)}&action=magic-login&token=${issued.token}`
  }

  // Build email HTML
  const emailHtml = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f5f5f5;font-family:Arial,sans-serif;">
  <div style="max-width:600px;margin:20px auto;background:white;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.1);">
    ${emailBrandHeader('Sign In to Bharat AI Innovation 2026', 'Conference &amp; Exhibition 2026 &bull; 20&ndash;21 Nov 2026 &bull; WTC Mumbai')}
    <div style="padding:32px;">
      <p style="color:#333;line-height:1.6;margin:0 0 16px;">Hi <strong>${attendee.name}</strong>,</p>
      <p style="color:#555;line-height:1.6;margin:0 0 24px;">Click the button below to sign in to the Bharat AI Innovation 2026. This link will log you in automatically — no password needed.</p>
      <div style="text-align:center;margin:24px 0;">
        ${loginCode ? `<p style="color:#444;font-size:14px;margin:0 0 18px;">Or enter this code in the app:<br><span style="display:inline-block;margin-top:8px;font-family:monospace;font-size:28px;letter-spacing:6px;font-weight:bold;color:#1E2140;">${loginCode}</span><br><span style="font-size:12px;color:#888;">Expires in 15 minutes. Never share it &mdash; we will not ask you for it.</span></p>` : ''}
        <a href="${magicLink}" style="display:inline-block;padding:14px 32px;background:linear-gradient(135deg,#6366f1,#4f46e5);color:white;text-decoration:none;border-radius:10px;font-weight:bold;font-size:15px;">
          🔑 Sign In Now
        </a>
      </div>
      <p style="color:#999;font-size:12px;text-align:center;margin:16px 0 0;">If you didn't request this, you can safely ignore this email.</p>
    </div>
    <div style="text-align:center;padding:16px;border-top:1px solid #eee;">
      <p style="color:#999;font-size:12px;margin:0;">Bharat AI Innovation 2026 • World Trade Center, Mumbai</p>
    </div>
  </div>
</body></html>`

  // Send via Elastic Email
  const apiKeyRow = await c.env.DB.prepare("SELECT value FROM app_settings WHERE key = 'elastic_email_api_key'").first() as any
  const senderRow = await c.env.DB.prepare("SELECT value FROM app_settings WHERE key = 'sender_email'").first() as any
  const senderNameRow = await c.env.DB.prepare("SELECT value FROM app_settings WHERE key = 'sender_name'").first() as any

  if (!apiKeyRow?.value) {
    return c.json({ error: 'Email service not configured.' }, 500)
  }

  const fromEmail = senderEmailOrDefault(senderRow?.value)
  const fromName = senderNameRow?.value || 'Bharat AI Innovation Conference & Exhibition 2026'

  try {
    const payload = {
      Recipients: { To: [normalizedEmail] },
      Content: {
        Body: [{ ContentType: "HTML", Content: emailHtml, Charset: "utf-8" }],
        From: `${fromName} <${fromEmail}>`,
        Subject: 'Sign In to Bharat AI Innovation 2026'
      },
      Options: { TrackClicks: false, TrackOpens: false }
    }
    const res = await fetch('https://api.elasticemail.com/v4/emails/transactional', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-ElasticEmail-ApiKey': apiKeyRow.value
      },
      body: JSON.stringify(payload)
    })
    const result = await res.json() as any
    if (!res.ok) {
      return c.json({ error: result.Error || 'Failed to send magic link email' }, 500)
    }
    return c.json({ success: true, message: NEUTRAL_SIGNIN_REPLY })
  } catch (e: any) {
    return c.json({ error: 'Failed to send email: ' + e.message }, 500)
  }
})

// Track delegate pass download
app.post('/api/attendees/:id/track-pass-download', async (c) => {
  const id = c.req.param('id')
  const denied = await requireSelf(c, id); if (denied) return denied
  await c.env.DB.prepare('UPDATE attendees SET pass_downloaded_at = datetime("now") WHERE id = ? AND pass_downloaded_at IS NULL').bind(id).run()
  return c.json({ success: true })
})

/* Track the shareable social card. Separate column from the pass on purpose: the
 * pass is a document everyone confirmed has to fetch, this one is only taken by
 * people pleased enough to tell their network, and only the second number says
 * whether the card was worth building.
 *
 * Set once and never overwritten - taking the square and then the story is one
 * person sharing once. Answers success:false rather than 500 while migration 0031
 * is unapplied, because a share that is merely uncounted must not look to the
 * delegate like a share that failed. */
app.post('/api/attendees/:id/track-social-card', async (c) => {
  const id = c.req.param('id')
  const denied = await requireSelf(c, id); if (denied) return denied
  try {
    await c.env.DB.prepare(
      'UPDATE attendees SET social_card_downloaded_at = datetime("now") WHERE id = ? AND social_card_downloaded_at IS NULL'
    ).bind(id).run()
    return c.json({ success: true })
  } catch {
    return c.json({ success: false, reason: 'not_migrated' })
  }
})

