// ==================== CONNECTION APIs ====================

app.get('/api/attendees/:id/connections', async (c) => {
  const attendeeId = c.req.param('id')
  const denied = await requireSelf(c, attendeeId); if (denied) return denied
  const { results } = await c.env.DB.prepare(`
    SELECT c.*, 
      CASE WHEN c.from_attendee_id = ? THEN a2.name ELSE a1.name END as other_name,
      CASE WHEN c.from_attendee_id = ? THEN a2.email ELSE a1.email END as other_email,
      CASE WHEN c.from_attendee_id = ? THEN a2.company ELSE a1.company END as other_company,
      CASE WHEN c.from_attendee_id = ? THEN a2.job_title ELSE a1.job_title END as other_job_title,
      CASE WHEN c.from_attendee_id = ? THEN a2.id ELSE a1.id END as other_id,
      CASE WHEN (CASE WHEN c.from_attendee_id = ? THEN a2.last_login_at ELSE a1.last_login_at END) > datetime('now', '-${ONLINE_WINDOW_MINUTES} minutes') THEN 1 ELSE 0 END as other_online,
      CASE WHEN c.from_attendee_id = ? THEN a2.avatar_url ELSE a1.avatar_url END as other_avatar,
      CASE WHEN c.from_attendee_id = ? THEN a2.badge_type ELSE a1.badge_type END as other_badge
    FROM connections c
    JOIN attendees a1 ON c.from_attendee_id = a1.id
    JOIN attendees a2 ON c.to_attendee_id = a2.id
    WHERE c.from_attendee_id = ? OR c.to_attendee_id = ?
    ORDER BY c.created_at DESC
  `).bind(attendeeId, attendeeId, attendeeId, attendeeId, attendeeId, attendeeId, attendeeId, attendeeId, attendeeId, attendeeId).all()
  return c.json(results)
})

// ==================== NETWORKING ENTITLEMENT & ETIQUETTE ====================

// Only the free Visitor Pass is barred from STARTING a conversation. Every other
// badge - Delegate, VIP, Academic, Organiser, Exhibitor, Speaker, Jury, Media -
// may initiate. Mirrors isVisitorPass() in the app so the two cannot drift.
//
// Receiving, accepting and replying are deliberately NOT gated, and must never be.
// A request its recipient is structurally unable to answer is worth nothing to the
// Delegate who paid to send it. Every one of the first 17 requests went to a
// Visitor, which is a large part of why none was ever accepted.
const canInitiateNetworking = (badgeType: unknown): boolean =>
  !/visitor/i.test(String(badgeType ?? ''))

// What a profile must carry before its owner may approach a stranger. The person
// deciding has to know who is asking and what they do; that is the whole
// difference between business networking and a dating app. Photo and LinkedIn are
// pushed hard in the UI but never required - a hard photo gate would stop the 95%
// who have not uploaded one.
function missingNetworkingProfileFields(a: any): string[] {
  const has = (v: any) => { const t = String(v ?? '').trim(); return t.length > 0 && t !== '-' }
  const missing: string[] = []
  if (!has(a?.job_title)) missing.push('your designation')
  if (!has(a?.company)) missing.push('your organisation')
  if (!has(a?.industry)) missing.push('your industry')
  if (!has(a?.interests)) missing.push('what you work on')
  return missing
}

// A stated reason, not a wave. The Connect button used to post a hardcoded
// "Would love to connect!" on everyone's behalf - all 17 requests in the database
// carry that identical string. There was nothing for the recipient to judge, so
// nobody judged it. The sender now has to say what they want to talk about.
const CONNECT_REASON_MIN = 15
const CONNECT_REASON_MAX = 500
const CANNED_REASONS = new Set([
  'would love to connect', 'love to connect', 'lets connect', "let's connect",
  'connect', 'hi', 'hello', 'hey', 'hi there', 'networking', 'interested',
])
function connectionReasonProblem(note: unknown): string | null {
  const t = String(note ?? '').replace(/\s+/g, ' ').trim()
  if (!t) return 'Please say why you would like to connect.'
  if (CANNED_REASONS.has(t.toLowerCase().replace(/[.!]+$/, '')))
    return 'Please say something specific about what you would like to talk about.'
  if (t.length < CONNECT_REASON_MIN)
    return 'Please write at least ' + CONNECT_REASON_MIN + ' characters about what you would like to talk about.'
  if (t.length > CONNECT_REASON_MAX) return 'Please keep your note under 500 characters.'
  return null
}

// A one-click Accept / Not now link for the notification email. Signed, scoped to
// a single connection row, and valid for 60 days - past the event, but not
// forever, because the link travels in email and email gets forwarded.
//
// It grants EXACTLY those two actions on EXACTLY that one row. It deliberately
// does NOT issue a session: a forwarded mail must never become a way into
// somebody's account. Reading the thread or replying still requires signing in.
const CONNECT_TOKEN_DAYS = 60
const connectTokenSecret = (c: any): string => attendeeSessionSecret(c) || passTokenSecret(c)

async function connectionActionToken(c: any, connId: any): Promise<string> {
  const secret = connectTokenSecret(c)
  if (!secret) return ''
  const exp = Math.floor(Date.now() / 1000) + CONNECT_TOKEN_DAYS * 86400
  const body = String(connId) + '.' + exp
  return body + '.' + (await hmacHexA(secret, 'conn:' + body)).slice(0, 32)
}

async function verifyConnectionActionToken(c: any, token: unknown): Promise<number | null> {
  const secret = connectTokenSecret(c)
  if (!secret) return null
  const parts = String(token ?? '').split('.')
  if (parts.length !== 3) return null
  const [id, exp, sig] = parts
  if (!/^\d+$/.test(id) || !/^\d+$/.test(exp)) return null
  if (parseInt(exp, 10) * 1000 < Date.now()) return null
  const expected = (await hmacHexA(secret, 'conn:' + id + '.' + exp)).slice(0, 32)
  return safeEqualA(sig, expected) ? parseInt(id, 10) : null
}

app.post('/api/connections', async (c) => {
  const body = await c.req.json()
  const { event_id, from_attendee_id, to_attendee_id, message } = body
  const denied = await requireSelf(c, from_attendee_id); if (denied) return denied

  if (String(from_attendee_id) === String(to_attendee_id)) {
    return c.json({ error: 'You cannot connect with yourself.' }, 400)
  }

  // Who is asking, and are they allowed to ask. The client hides the button from
  // Visitors, but the client is not the authority: the profile modal's Connect
  // button carried no such check, which is how every request in the table came
  // from a Visitor Pass in the first place.
  const sender = await c.env.DB.prepare(
    'SELECT name, badge_type, job_title, company, industry, interests FROM attendees WHERE id = ?'
  ).bind(from_attendee_id).first() as any
  if (!sender) return c.json({ error: 'Please sign in again to continue.' }, 401)

  if (!canInitiateNetworking(sender.badge_type)) {
    return c.json({
      error: 'upgrade_required',
      message: 'Starting a conversation is part of the Delegate, Academic and VIP passes. Your Visitor Pass can still receive and accept requests.',
    }, 402)
  }

  const gaps = missingNetworkingProfileFields(sender)
  if (gaps.length) {
    return c.json({
      error: 'profile_incomplete',
      message: 'Please add ' + humanList(gaps) + ' first, so they can see who is reaching out.',
      missing: gaps,
    }, 400)
  }

  const reasonProblem = connectionReasonProblem(message)
  if (reasonProblem) return c.json({ error: 'reason_required', message: reasonProblem }, 400)

  const note = String(message).replace(/\s+/g, ' ').trim()

  try {
    const ins = await c.env.DB.prepare(
      'INSERT INTO connections (event_id, from_attendee_id, to_attendee_id, message) VALUES (?, ?, ?, ?)'
    ).bind(event_id, from_attendee_id, to_attendee_id, note).run()

    // The row is committed; the mail goes out behind the response and cannot fail it.
    // The UNIQUE(event_id, from, to) constraint means a repeat request throws above
    // and returns 409, so re-tapping Connect cannot re-mail.
    await scheduleNotification(c, notifyConnectionRequest(c, ins.meta.last_row_id, from_attendee_id, to_attendee_id, note))
    return c.json({ success: true }, 201)
  } catch (e: any) {
    if (e.message?.includes('UNIQUE')) return c.json({ error: 'You have already asked to connect with them.' }, 409)
    return c.json({ error: 'Failed to create connection' }, 400)
  }
})

// Accept or decline straight from the email, with no sign-in. Deliberately a POST
// from a button on /c/:token and never a GET side effect: Gmail, Outlook and every
// corporate link scanner fetch the URLs in a message, and a GET that accepted
// would have those scanners answering people's invitations for them.
app.post('/api/connections/respond', async (c) => {
  const { token, action } = await c.req.json().catch(() => ({} as any))
  if (action !== 'accepted' && action !== 'declined') {
    return c.json({ error: 'Unknown action.' }, 400)
  }
  const connId = await verifyConnectionActionToken(c, token)
  if (!connId) return c.json({ error: 'This link has expired. Please open the app to reply.' }, 403)

  const row = await c.env.DB.prepare('SELECT status FROM connections WHERE id = ?').bind(connId).first() as any
  if (!row) return c.json({ error: 'That request no longer exists.' }, 404)

  // Idempotent: a second click, or a double-tap on a slow phone, reports the
  // settled state rather than re-firing the acceptance mail.
  if (row.status === action) return c.json({ success: true, status: action, repeated: true })
  if (row.status !== 'pending') {
    return c.json({ success: true, status: row.status, repeated: true })
  }

  const upd = await c.env.DB.prepare(
    'UPDATE connections SET status = ? WHERE id = ? AND status = ?'
  ).bind(action, connId, 'pending').run()

  if (upd?.meta?.changes === 1 && action === 'accepted') {
    await scheduleNotification(c, notifyConnectionAccepted(c, connId))
  }
  return c.json({ success: true, status: action })
})

app.put('/api/connections/:id', async (c) => {
  const id = c.req.param('id')
  const { status } = await c.req.json()
  // The param is the connection id, not an attendee id, so requireSelf(c, id) would
  // be meaningless here — load the row and authorise against its participants.
  if (!isAdminRequest(c) && attendeeSessionSecret(c)) {
    const me = await verifyAttendeeSession(c)
    if (!me) return c.json({ error: 'Please sign in again to continue.' }, 401)
    const row = await c.env.DB.prepare('SELECT from_attendee_id, to_attendee_id FROM connections WHERE id = ?').bind(id).first() as any
    if (!row) return c.json({ error: 'Connection not found' }, 404)
    if (me !== row.from_attendee_id && me !== row.to_attendee_id) {
      return c.json({ error: 'You can only change your own connections.' }, 403)
    }
  }
  // Gate on a real transition: the client calls this straight from a button, and a
  // double-tap on Accept would otherwise mail the requester twice. IS NOT (not !=)
  // because a NULL status must still count as a move.
  const upd = await c.env.DB.prepare(
    'UPDATE connections SET status = ? WHERE id = ? AND status IS NOT ?'
  ).bind(status, id, status).run()
  // Decline stays deliberately silent -- "X declined you" helps nobody, and the app
  // already shows the status.
  if (upd?.meta?.changes === 1 && status === 'accepted') {
    await scheduleNotification(c, notifyConnectionAccepted(c, id))
  }
  return c.json({ success: true })
})

// ==================== MESSAGE APIs ====================

app.get('/api/messages/:userId/:otherUserId', async (c) => {
  const userId = c.req.param('userId')
  const otherUserId = c.req.param('otherUserId')
  // Either participant may read the thread; nobody else. This route also marks
  // messages read, so an unauthenticated read used to clear the victim's badge.
  if (!isAdminRequest(c)) {
    const me = await verifyAttendeeSession(c)
    if (attendeeSessionSecret(c)) {
      if (!me) return c.json({ error: 'Please sign in again to continue.' }, 401)
      if (String(me) !== String(userId) && String(me) !== String(otherUserId)) {
        return c.json({ error: 'You can only read your own conversations.' }, 403)
      }
    }
  }
  const { results } = await c.env.DB.prepare(`
    SELECT m.*, a.name as sender_name 
    FROM messages m
    JOIN attendees a ON m.sender_id = a.id
    WHERE (m.sender_id = ? AND m.receiver_id = ?) OR (m.sender_id = ? AND m.receiver_id = ?)
    ORDER BY m.created_at ASC
  `).bind(userId, otherUserId, otherUserId, userId).all()

  // Mark as read
  await c.env.DB.prepare(
    'UPDATE messages SET is_read = 1 WHERE sender_id = ? AND receiver_id = ?'
  ).bind(otherUserId, userId).run()

  return c.json(results)
})

app.post('/api/messages', async (c) => {
  const body = await c.req.json()
  const { event_id, sender_id, receiver_id, content } = body
  const denied = await requireSelf(c, sender_id); if (denied) return denied

  // Read BEFORE the insert. Afterwards the message we are about to write is itself
  // unread and would suppress its own notification. One query carries both parties
  // and both throttle counters, so this costs a single round trip.
  let notify: any = null
  try {
    notify = await c.env.DB.prepare(
      `SELECT r.name AS to_name, r.email AS to_email, s.name AS from_name,
              (SELECT COUNT(*) FROM messages m
                 WHERE m.sender_id = s.id AND m.receiver_id = r.id AND m.is_read = 0) AS unread_from_sender,
              (SELECT COUNT(*) FROM messages m
                 WHERE m.sender_id = s.id AND m.receiver_id = r.id
                   AND m.created_at > datetime('now', '-${MESSAGE_EMAIL_QUIET_MINUTES} minutes')) AS recent_from_sender
         FROM attendees r JOIN attendees s ON s.id = ?
        WHERE r.id = ?`
    ).bind(sender_id, receiver_id).first()
  } catch { /* a notification lookup must never block a message */ }

  const result = await c.env.DB.prepare(
    'INSERT INTO messages (event_id, sender_id, receiver_id, content) VALUES (?, ?, ?, ?)'
  ).bind(event_id, sender_id, receiver_id, content).run()

  // Two conditions, both necessary. unread_from_sender = 0 means the recipient has
  // no un-opened message from this person, so we are not shouting about a nudge they
  // have already been sent. recent_from_sender = 0 caps it at one mail per quiet
  // window, which is what stops a live back-and-forth -- where the recipient is in
  // the app, reading and clearing is_read after every line -- becoming a mail a line.
  // GET /api/messages/:userId/:otherUserId sets is_read = 1 when they open the
  // thread, so reading is what re-arms the notification.
  if (notify && notify.to_email &&
      !netSamePerson(sender_id, receiver_id) &&
      Number(notify.unread_from_sender) === 0 &&
      Number(notify.recent_from_sender) === 0) {
    await scheduleNotification(c, notifyNewMessage(c, notify, content))
  }

  return c.json({ id: result.meta.last_row_id, success: true }, 201)
})

app.get('/api/attendees/:id/unread', async (c) => {
  const id = c.req.param('id')
  const denied = await requireSelf(c, id); if (denied) return denied
  const result = await c.env.DB.prepare(
    'SELECT COUNT(*) as count FROM messages WHERE receiver_id = ? AND is_read = 0'
  ).bind(id).first()
  return c.json(result)
})

// ==================== BOARDROOM APIs ====================
//
// Every route here answers as if the rooms simply had nothing booked when
// migration 0029 has not been applied. That is deliberate: the code reaches
// production before the migration is hand-run, and an empty grid is recoverable
// where a 500 is not — the innovation_talks table taught us that the expensive
// way, taking down two tabs at once.

app.get('/api/events/:id/rooms', async (c) => {
  const eventId = c.req.param('id')
  const shell = { rooms: [] as any[], days: ROOM_DAYS, slot_hours: ROOM_SLOT_HOURS, gst_percent: ROOM_GST_PERCENT }
  if (!(await roomBookingEnabled(c))) return c.json({ ready: false, ...shell })
  try {
    const { results } = await c.env.DB.prepare(
      'SELECT * FROM meeting_rooms WHERE event_id = ? AND is_active = 1 ORDER BY sort_order ASC'
    ).bind(eventId).all()
    return c.json({ ready: true, ...shell, rooms: results || [] })
  } catch (e: any) {
    if (/no such table/i.test(String(e?.message || ''))) return c.json({ ready: false, ...shell })
    throw e
  }
})

// Which hours of one room are still free on one day. Anonymous callers learn that
// an hour is gone but never who took it — same instinct as ATTENDEE_PUBLIC_COLS.
app.get('/api/events/:id/rooms/:roomId/availability', async (c) => {
  const roomId = c.req.param('roomId')
  const date = c.req.query('date') || ROOM_DAYS[0]
  if (!ROOM_DAYS.includes(date)) {
    return c.json({ error: 'Rooms are only bookable on 20-21 November 2026.' }, 400)
  }
  const shell = { room_id: Number(roomId), date, gst_percent: ROOM_GST_PERCENT }
  if (!(await roomBookingEnabled(c))) return c.json({ ready: false, ...shell, slots: [] })

  const admin = isAdminRequest(c)
  try {
    const { results } = await c.env.DB.prepare(
      `SELECT id, slot_start, status, kind, attendee_id, title FROM room_bookings
        WHERE room_id = ? AND slot_date = ? AND status IN ('held', 'confirmed')`
    ).bind(roomId, date).all()
    const taken: Record<string, any> = {}
    for (const r of (results || []) as any[]) taken[r.slot_start] = r
    const slots = ROOM_SLOT_HOURS.map(h => {
      const start = `${date} ${h}`
      const t = taken[start]
      return {
        start, end: roomSlotEnd(start),
        available: !t,
        status: t ? t.status : null,
        kind: t ? t.kind : null,
        ...(t && admin ? { booking_id: t.id, title: t.title, attendee_id: t.attendee_id } : {}),
      }
    })
    return c.json({ ready: true, ...shell, slots })
  } catch (e: any) {
    if (/no such table/i.test(String(e?.message || ''))) return c.json({ ready: false, ...shell, slots: [] })
    throw e
  }
})

// A signed-in attendee reserves one to four consecutive hours. Status is always
// 'held', never 'confirmed': at Rs 10,000-15,000 an hour plus GST the room is not
// sold by a button, it is invoiced by the team, who then flip the hold.
app.post('/api/room-bookings', async (c) => {
  const b = await c.req.json() as any
  const denied = await requireSelf(c, b.attendee_id); if (denied) return denied
  if (!(await roomBookingEnabled(c))) return c.json({ error: 'Room booking is not available yet.' }, 503)

  const slotDate = String(b.slot_date || '')
  if (!ROOM_DAYS.includes(slotDate)) {
    return c.json({ error: 'Rooms are only bookable on 20-21 November 2026.' }, 400)
  }
  const starts = Array.from(new Set((Array.isArray(b.slot_starts) ? b.slot_starts : []).map(String)))
  if (!starts.length || starts.length > 4) {
    return c.json({ error: 'Pick between one and four hours.' }, 400)
  }
  const allowed = ROOM_SLOT_HOURS.map(h => `${slotDate} ${h}`)
  if (starts.some(s => !allowed.includes(s))) {
    return c.json({ error: 'Rooms are bookable between 09:00 and 18:00 only.' }, 400)
  }

  try {
    const room = await c.env.DB.prepare(
      'SELECT id, label, wtc_name, price_inr FROM meeting_rooms WHERE id = ? AND is_active = 1'
    ).bind(b.room_id).first() as any
    if (!room) return c.json({ error: 'Room not found' }, 404)

    // One D1 batch, so a two-hour request never half-lands: the batch is a
    // transaction, and a collision on any hour rolls the whole reservation back.
    // The partial unique index — not the check above — is what makes that true.
    const groupRef = randomHex(8)
    await c.env.DB.batch(starts.map(s => c.env.DB.prepare(
      `INSERT INTO room_bookings (event_id, room_id, slot_date, slot_start, slot_end, group_ref, kind,
         attendee_id, meeting_id, title, headcount, notes, contact_name, contact_email, contact_phone, price_inr, status)
       VALUES (?, ?, ?, ?, ?, ?, 'booking', ?, ?, ?, ?, ?, ?, ?, ?, ?, 'held')`
    ).bind(
      b.event_id || 1, room.id, slotDate, s, roomSlotEnd(s), groupRef,
      b.attendee_id, b.meeting_id || null, b.title || 'Private meeting',
      b.headcount || null, b.notes || '',
      b.contact_name || '', b.contact_email || '', b.contact_phone || '',
      room.price_inr
    )))

    return c.json({
      success: true, group_ref: groupRef, status: 'held',
      room_id: room.id, room_label: room.label, wtc_name: room.wtc_name,
      slot_date: slotDate, hours: starts.length,
      total_inr: room.price_inr * starts.length, gst_percent: ROOM_GST_PERCENT,
    }, 201)
  } catch (e: any) {
    const msg = String(e?.message || '')
    if (/UNIQUE constraint/i.test(msg)) {
      return c.json({ error: 'That hour has just been taken. Pick another.' }, 409)
    }
    if (/no such table/i.test(msg)) return c.json({ error: 'Room booking is not available yet.' }, 503)
    throw e
  }
})

app.get('/api/attendees/:id/room-bookings', async (c) => {
  const attendeeId = c.req.param('id')
  const denied = await requireSelf(c, attendeeId); if (denied) return denied
  if (!(await roomBookingEnabled(c))) return c.json([])
  try {
    const { results } = await c.env.DB.prepare(`
      SELECT rb.*, r.label AS room_label, r.wtc_name, r.capacity, r.layout
      FROM room_bookings rb JOIN meeting_rooms r ON rb.room_id = r.id
      WHERE rb.attendee_id = ? AND rb.status <> 'cancelled'
      ORDER BY rb.slot_start ASC
    `).bind(attendeeId).all()
    return c.json(results)
  } catch (e: any) {
    if (/no such table/i.test(String(e?.message || ''))) return c.json([])
    throw e
  }
})

app.put('/api/room-bookings/:id', async (c) => {
  const id = c.req.param('id')
  const { status } = await c.req.json() as any
  // The attendee side of a booking can only ever release it. Confirming and
  // re-pricing live on /api/admin/room-bookings/:id, behind the admin guard.
  if (status !== 'cancelled') return c.json({ error: 'Only cancellation is allowed here.' }, 400)
  if (!(await roomBookingEnabled(c))) return c.json({ error: 'Room booking is not available yet.' }, 503)

  try {
    // Same shape as meetings: the param identifies the booking, not the caller.
    if (!isAdminRequest(c) && attendeeSessionSecret(c)) {
      const me = await verifyAttendeeSession(c)
      if (!me) return c.json({ error: 'Please sign in again to continue.' }, 401)
      const row = await c.env.DB.prepare('SELECT attendee_id FROM room_bookings WHERE id = ?').bind(id).first() as any
      if (!row) return c.json({ error: 'Booking not found' }, 404)
      if (me !== row.attendee_id) return c.json({ error: 'You can only change your own bookings.' }, 403)
    }
    // Cancel the whole reservation, not one hour of it — a person who books
    // 10:00-12:00 and cancels means both hours, and half a meeting helps nobody.
    const upd = await c.env.DB.prepare(
      `UPDATE room_bookings
          SET status = 'cancelled', cancelled_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
        WHERE status IN ('held', 'confirmed')
          AND ((group_ref IS NOT NULL AND group_ref = (SELECT group_ref FROM room_bookings WHERE id = ?)) OR id = ?)`
    ).bind(id, id).run()
    return c.json({ success: true, hours_released: upd?.meta?.changes || 0 })
  } catch (e: any) {
    if (/no such table/i.test(String(e?.message || ''))) return c.json({ error: 'Room booking is not available yet.' }, 503)
    throw e
  }
})

