app.get('/api/attendees/:id/meetings', async (c) => {
  const attendeeId = c.req.param('id')
  const denied = await requireSelf(c, attendeeId); if (denied) return denied
  const { results } = await c.env.DB.prepare(`
    SELECT m.*, 
      a1.name as requester_name, a1.company as requester_company,
      a2.name as requestee_name, a2.company as requestee_company
    FROM meetings m
    JOIN attendees a1 ON m.requester_id = a1.id
    JOIN attendees a2 ON m.requestee_id = a2.id
    WHERE m.requester_id = ? OR m.requestee_id = ?
    ORDER BY m.meeting_time ASC
  `).bind(attendeeId, attendeeId).all()
  return c.json(results)
})

app.post('/api/meetings', async (c) => {
  const body = await c.req.json()
  const { event_id, requester_id, requestee_id, title, meeting_time, duration_minutes, location, notes } = body
  const denied = await requireSelf(c, requester_id); if (denied) return denied

  const result = await c.env.DB.prepare(
    'INSERT INTO meetings (event_id, requester_id, requestee_id, title, meeting_time, duration_minutes, location, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
  ).bind(event_id, requester_id, requestee_id, title, meeting_time, duration_minutes || 15, location || '', notes || '').run()

  // A meeting request nobody is told about is a slot that will not be honoured. The
  // row is committed above, so the mail runs behind the response and its failure is
  // invisible to the requester. Reload by id rather than trusting the body, so the
  // mail shows what was actually stored -- including the duration default applied here.
  await scheduleNotification(c, notifyMeetingRequested(c, result.meta.last_row_id))

  return c.json({ id: result.meta.last_row_id, success: true }, 201)
})

app.put('/api/meetings/:id', async (c) => {
  const id = c.req.param('id')
  const { status } = await c.req.json()
  // Same shape as connections: the param identifies the meeting, not the caller.
  if (!isAdminRequest(c) && attendeeSessionSecret(c)) {
    const me = await verifyAttendeeSession(c)
    if (!me) return c.json({ error: 'Please sign in again to continue.' }, 401)
    const row = await c.env.DB.prepare('SELECT requester_id, requestee_id FROM meetings WHERE id = ?').bind(id).first() as any
    if (!row) return c.json({ error: 'Meeting not found' }, 404)
    if (me !== row.requester_id && me !== row.requestee_id) {
      return c.json({ error: 'You can only change your own meetings.' }, 403)
    }
  }
  // Same transition gate as connections: Accept is a button, and buttons get
  // double-tapped. Only a status that actually moved mails anyone.
  const upd = await c.env.DB.prepare(
    'UPDATE meetings SET status = ? WHERE id = ? AND status IS NOT ?'
  ).bind(status, id, status).run()
  // Always the requester, which is right: the UI only offers accept/decline to the
  // other side. 'cancelled' is excluded because that is the requester acting on
  // their own meeting -- mailing them their own click is noise.
  if (upd?.meta?.changes === 1 && (status === 'accepted' || status === 'declined')) {
    await scheduleNotification(c, notifyMeetingResponse(c, id, status))
  }
  return c.json({ success: true })
})

// ==================== EXHIBITOR APIs ====================

app.get('/api/events/:id/exhibitors', async (c) => {
  const eventId = c.req.param('id')
  const category = c.req.query('category')
  const search = c.req.query('search')

  let query = 'SELECT * FROM exhibitors WHERE event_id = ?'
  const params: any[] = [eventId]

  if (category) {
    query += ' AND category = ?'
    params.push(category)
  }
  if (search) {
    query += ' AND (company_name LIKE ? OR description LIKE ? OR products LIKE ?)'
    const s = `%${search}%`
    params.push(s, s, s)
  }

  query += ' ORDER BY booth_size DESC, company_name ASC'

  const { results } = await c.env.DB.prepare(query).bind(...params).all()
  return c.json(results)
})

app.get('/api/exhibitors/:id', async (c) => {
  const id = c.req.param('id')
  const exhibitor = await c.env.DB.prepare('SELECT * FROM exhibitors WHERE id = ?').bind(id).first()
  if (!exhibitor) return c.json({ error: 'Exhibitor not found' }, 404)
  return c.json(exhibitor)
})

app.post('/api/exhibitors/:id/visit', async (c) => {
  const exhibitorId = c.req.param('id')
  const { attendee_id, event_id, interested, notes } = await c.req.json()
  const denied = await requireSelf(c, attendee_id); if (denied) return denied

  await c.env.DB.prepare(
    'INSERT INTO booth_visits (exhibitor_id, attendee_id, event_id, interested, notes) VALUES (?, ?, ?, ?, ?)'
  ).bind(exhibitorId, attendee_id, event_id, interested ? 1 : 0, notes || '').run()

  await c.env.DB.prepare(
    'UPDATE exhibitors SET visitor_count = visitor_count + 1 WHERE id = ?'
  ).bind(exhibitorId).run()

  return c.json({ success: true }, 201)
})

app.get('/api/events/:id/exhibitors/categories', async (c) => {
  const eventId = c.req.param('id')
  const { results } = await c.env.DB.prepare(
    'SELECT DISTINCT category FROM exhibitors WHERE event_id = ? ORDER BY category'
  ).bind(eventId).all()
  return c.json(results.map((r: any) => r.category))
})

// ==================== IMAGE PROXY (for CORS-free canvas drawing) ====================
app.get('/api/image-proxy', async (c) => {
  const url = c.req.query('url')
  if (!url) return c.text('Missing url param', 400)
  // Narrow allowlist. The QR service is here because loading it directly onto the
  // pass canvas would work, but proxying keeps the fetch same-origin (no tainted
  // canvas, no CORS surprise) and lets Cloudflare cache the code.
  // The favicon service is the employer logo on the shareable social card. Nothing
  // in this app stores a company logo, so it is looked up from the delegate's own
  // website_url (or their work email domain) at draw time. Pinned to the one exact
  // endpoint rather than the host: s2/favicons only ever returns an icon for a
  // domain, so widening the list this far does not turn the proxy into a general
  // fetcher for anything else on google.com.
  const PROXY_ALLOWED = [
    'https://bharataiinnovation.com/',
    'https://api.qrserver.com/',
    'https://www.google.com/s2/favicons?',
  ]
  if (!PROXY_ALLOWED.some(prefix => url.startsWith(prefix))) return c.text('Domain not allowed', 403)
  try {
    const resp = await fetch(url)
    if (!resp.ok) return c.text('Upstream error', resp.status)
    const buf = await resp.arrayBuffer()
    const ct = resp.headers.get('content-type') || 'image/png'
    return new Response(buf, {
      headers: {
        'Content-Type': ct,
        'Access-Control-Allow-Origin': '*',
        'Cache-Control': 'public, max-age=86400',
      }
    })
  } catch(e: any) {
    return c.text('Fetch failed: ' + e.message, 500)
  }
})

// ==================== EXHIBITION FLOOR: LIVE AVAILABILITY ====================
//
// The floor plan shipped as a static array in public/js/floor-plan-data.js with
// booked:false hardcoded on all 93 stands, so marking one sold meant editing a
// JS file and redeploying, and nothing tied it to the money already sitting in
// booth_requests. This is the read side of the fix.
//
// It is deliberately READ-ONLY. At ~Rs 32,250 per sqm on a GST invoice the team
// allocates, exactly as the boardrooms are quoted rather than self-served. What
// the public gets from this endpoint is urgency — what has gone and what is left
// — not a checkout and not a price list.
//
// Answers 200 with ready:false while migration 0030 is unapplied, never a 500,
// for the same reason every boardroom route does.
app.get('/api/events/:id/booths', async (c) => {
  const eventId = c.req.param('id')
  const zero = { total: 0, available: 0, held: 0, sold: 0, blocked: 0, sold_sqm: 0 }
  if (!(await boothInventoryEnabled(c))) return c.json({ ready: false, booths: [], summary: zero })
  try {
    // A released allocation is history, not an occupant, and a hold past its expiry
    // is an option nobody took up — both must read as space on the market here, or
    // the public plan goes on showing a stand as gone months after it came back.
    const live = await boothLifecycleEnabled(c)
    const today = boothToday()
    const { results } = await c.env.DB.prepare(
      `SELECT b.code, b.type_key, b.name, b.dim, b.sqm, b.zone, b.fx, b.fy, b.fw, b.fh,
              ba.status AS alloc_status, ba.company_name AS alloc_company
              ${live ? ', ba.hold_expires_at AS alloc_hold_expires_at' : ''}
         FROM booths b
         LEFT JOIN booth_allocations ba ON ba.booth_id = b.id AND ba.event_id = b.event_id${boothLiveOnly(live)}
        WHERE b.event_id = ?
        ORDER BY b.sort_order ASC, b.id ASC`
    ).bind(eventId).all()

    const summary = { ...zero }
    const booths = ((results || []) as any[]).map(r => {
      // 'confirmed' is a sale, 'held' is a negotiation, 'blocked' is the organiser
      // taking space off the market. No allocation row at all means available — and
      // so does a hold whose clock ran out, because nothing else will ever put it
      // back: there is no cron, so the lapse happens here, on the way out.
      const lapsed = live && boothHoldLapsed(r.alloc_status, r.alloc_hold_expires_at, today)
      const status = lapsed ? 'available'
        : r.alloc_status === 'confirmed' ? 'sold'
        : r.alloc_status === 'held' ? 'held'
        : r.alloc_status === 'blocked' ? 'blocked'
        : 'available'
      summary.total++
      const bucket = summary as any
      bucket[status]++
      if (status === 'sold') summary.sold_sqm += Number(r.sqm || 0)
      return {
        code: r.code, type_key: r.type_key, name: r.name, dim: r.dim,
        sqm: Number(r.sqm || 0), zone: r.zone,
        fx: r.fx, fy: r.fy, fw: r.fw, fh: r.fh,
        status,
        // Only a completed sale names its occupant. A held stand must not leak who
        // is mid-negotiation — that is a competitor's shopping list, and the same
        // instinct that keeps ATTENDEE_PUBLIC_COLS narrow.
        company: status === 'sold' ? (r.alloc_company || null) : null,
      }
    })
    // 2.25 sqm pods make this a float sum; round once at the end rather than
    // publishing 47.250000000000004.
    summary.sold_sqm = Math.round(summary.sold_sqm * 100) / 100
    return c.json({ ready: true, booths, summary })
  } catch (e: any) {
    // "no such column" as well as "no such table", now that the lifecycle columns
    // are read here: a database carrying an earlier draft of 0030 must read as
    // not-live and let the static plan keep answering, never 500 at a visitor.
    if (/no such (table|column)/i.test(String(e?.message || ''))) {
      return c.json({ ready: false, booths: [], summary: zero })
    }
    throw e
  }
})

