// ==================== USER DASHBOARD APIs ====================

app.get('/api/attendees/:id/dashboard', async (c) => {
  const id = c.req.param('id')
  const denied = await requireSelf(c, id); if (denied) return denied

  // Eleven sequential awaits: a profile, seven counts, three lists. The seven counts
  // touch four different tables but are all scalar, so they collapse into a single
  // SELECT of sub-selects; that row plus the profile and the three lists go out as
  // ONE batch. Eleven round trips become one. requireSelf has already proved the
  // caller is this attendee, so the row exists and the lists cannot leak.
  // Ordinal `?` placeholders only (D1 does not reliably accept ?NNN), so the id is
  // bound once per placeholder - 11 times for the counts, 7 for the connections.
  const statsSql = `SELECT
      (SELECT COUNT(*) FROM connections WHERE (from_attendee_id = ? OR to_attendee_id = ?) AND status = 'accepted') AS connectionsAccepted,
      (SELECT COUNT(*) FROM connections WHERE to_attendee_id = ? AND status = 'pending') AS connectionsPending,
      (SELECT COUNT(*) FROM messages WHERE sender_id = ? OR receiver_id = ?) AS totalMessages,
      (SELECT COUNT(*) FROM messages WHERE receiver_id = ? AND is_read = 0) AS unreadMessages,
      (SELECT COUNT(*) FROM meetings WHERE (requester_id = ? OR requestee_id = ?) AND status = 'accepted') AS meetingsUpcoming,
      (SELECT COUNT(*) FROM meetings WHERE (requester_id = ? OR requestee_id = ?) AND status = 'pending') AS meetingsPending,
      (SELECT COUNT(*) FROM booth_visits WHERE attendee_id = ?) AS boothVisits`

  const batched = await c.env.DB.batch([
    // Was SELECT * — returned email, mobile and every other column, bypassing the
    // ATTENDEE_PUBLIC_COLS allowlist that protects the directory.
    c.env.DB.prepare(`SELECT ${isAdminRequest(c) ? '*' : ATTENDEE_PUBLIC_COLS + ', email, mobile, badge_type, rsvp_status, pass_downloaded_at'} FROM attendees WHERE id = ?`).bind(id),
    c.env.DB.prepare(statsSql).bind(...new Array(11).fill(id)),
    // Recent connections with names. other_online used to read the raw is_online
    // column, which is never cleared - every contact showed a green dot forever.
    // Same 15-minute window as ATTENDEE_PUBLIC_COLS so the dot means one thing.
    c.env.DB.prepare(`
      SELECT c.*,
        CASE WHEN c.from_attendee_id = ? THEN a2.name ELSE a1.name END as other_name,
        CASE WHEN c.from_attendee_id = ? THEN a2.email ELSE a1.email END as other_email,
        CASE WHEN c.from_attendee_id = ? THEN a2.company ELSE a1.company END as other_company,
        CASE WHEN c.from_attendee_id = ? THEN a2.id ELSE a1.id END as other_id,
        CASE WHEN (CASE WHEN c.from_attendee_id = ? THEN a2.last_login_at ELSE a1.last_login_at END) > datetime('now', '-${ONLINE_WINDOW_MINUTES} minutes') THEN 1 ELSE 0 END as other_online
      FROM connections c
      JOIN attendees a1 ON c.from_attendee_id = a1.id
      JOIN attendees a2 ON c.to_attendee_id = a2.id
      WHERE (c.from_attendee_id = ? OR c.to_attendee_id = ?) AND c.status = 'accepted'
      ORDER BY c.created_at DESC LIMIT 6
    `).bind(id, id, id, id, id, id, id),
    c.env.DB.prepare(`
      SELECT m.*,
        a1.name as requester_name, a1.company as requester_company,
        a2.name as requestee_name, a2.company as requestee_company
      FROM meetings m
      JOIN attendees a1 ON m.requester_id = a1.id
      JOIN attendees a2 ON m.requestee_id = a2.id
      WHERE (m.requester_id = ? OR m.requestee_id = ?) AND m.status IN ('accepted','pending')
      ORDER BY m.meeting_time ASC LIMIT 5
    `).bind(id, id),
    c.env.DB.prepare(`
      SELECT bv.*, e.company_name, e.booth_number, e.category
      FROM booth_visits bv
      JOIN exhibitors e ON bv.exhibitor_id = e.id
      WHERE bv.attendee_id = ?
      ORDER BY bv.visited_at DESC LIMIT 6
    `).bind(id),
  ])

  const attendee = (batched[0] as any)?.results?.[0]
  if (!attendee) return c.json({ error: 'Attendee not found' }, 404)
  const s = ((batched[1] as any)?.results?.[0]) || {}

  return c.json({
    profile: attendee,
    stats: {
      connectionsAccepted: s.connectionsAccepted || 0,
      connectionsPending: s.connectionsPending || 0,
      totalMessages: s.totalMessages || 0,
      unreadMessages: s.unreadMessages || 0,
      meetingsUpcoming: s.meetingsUpcoming || 0,
      meetingsPending: s.meetingsPending || 0,
      boothVisits: s.boothVisits || 0,
    },
    recentConnections: (batched[2] as any)?.results || [],
    upcomingMeetings: (batched[3] as any)?.results || [],
    visitedBooths: (batched[4] as any)?.results || [],
  })
})

// Update attendee profile
app.put('/api/attendees/:id/profile', async (c) => {
  const id = c.req.param('id')
  const denied = await requireSelf(c, id); if (denied) return denied
  const body = await c.req.json()
  const { name, company, job_title, bio, interests, linkedin_url, twitter_url, website_url, mobile, lunch_inclusion, arrival_time, city, industry } = body

  // city and industry are required at registration but were missing from this
  // statement, so the ~1,000 people who registered before that rule existed had no
  // way to supply them: the Edit Profile dialog could not send what the endpoint
  // would not accept. Both are only written when the caller sends them, so a client
  // that omits them cannot blank a value that is already there.
  const extra: string[] = []
  const extraVals: any[] = []
  if (city !== undefined) { extra.push('city = ?'); extraVals.push(String(city || '').trim()) }
  if (industry !== undefined && INDUSTRIES.includes(String(industry))) { extra.push('industry = ?'); extraVals.push(String(industry)) }

  await c.env.DB.prepare(
    'UPDATE attendees SET name=?, company=?, job_title=?, bio=?, interests=?, linkedin_url=?, twitter_url=?, website_url=?, mobile=?, lunch_inclusion=?, arrival_time=?' +
    (extra.length ? ', ' + extra.join(', ') : '') + ' WHERE id=?'
  ).bind(
    name, company || '', job_title || '', bio || '', interests || '',
    linkedin_url || '', twitter_url || '', website_url || '', mobile || '', lunch_inclusion || 'Yes', arrival_time || '', ...extraVals, id
  ).run()

  const updated = await c.env.DB.prepare('SELECT * FROM attendees WHERE id = ?').bind(id).first()
  return c.json(updated)
})

// Upload avatar photo for attendee (self-service or admin)
app.post('/api/attendees/:id/avatar', async (c) => {
  const id = c.req.param('id')
  const denied = await requireSelf(c, id); if (denied) return denied
  const attendee = await c.env.DB.prepare('SELECT id FROM attendees WHERE id = ?').bind(id).first()
  if (!attendee) return c.json({ error: 'Attendee not found' }, 404)

  const { image } = await c.req.json()
  if (!image) return c.json({ error: 'No image data provided' }, 400)

  const m = /^data:(image\/(?:png|jpe?g|webp|gif));base64,(.+)$/.exec(String(image))
  if (!m) return c.json({ error: 'Invalid image format. Must be a base64 data:image URL.' }, 400)
  if (image.length > 700000) {
    return c.json({ error: 'Image too large. Please use a smaller image (max ~500KB).' }, 400)
  }

  // Photos go to R2, and the row keeps only a URL.
  //
  // They used to be written into attendees.avatar_url as the base64 data URL itself.
  // avatar_url is in ATTENDEE_PUBLIC_COLS, so every photo was inlined into the
  // networking directory response on every load — that endpoint is already 428KB for
  // ~1,000 attendees, and at 500KB a photo it would have become hundreds of MB. The
  // whole database is 1.7MB today; this is what would have grown it past 500MB.
  if (c.env.UPLOADS) {
    const bytes = Uint8Array.from(atob(m[2]), ch => ch.charCodeAt(0))
    const ext = m[1].split('/')[1].replace('jpeg', 'jpg')
    const key = 'avatars/' + id + '-' + Date.now() + '.' + ext
    await c.env.UPLOADS.put(key, bytes, { httpMetadata: { contentType: m[1], cacheControl: 'public, max-age=31536000' } })
    const url = '/api/uploads/' + key
    // Remove the object the row pointed at, so replacing a photo does not orphan one.
    const prev = await c.env.DB.prepare('SELECT avatar_url FROM attendees WHERE id = ?').bind(id).first() as any
    await c.env.DB.prepare('UPDATE attendees SET avatar_url = ? WHERE id = ?').bind(url, id).run()
    if (prev?.avatar_url && String(prev.avatar_url).startsWith('/api/uploads/')) {
      try { await c.env.UPLOADS.delete(String(prev.avatar_url).slice('/api/uploads/'.length)) } catch {}
    }
    return c.json({ success: true, avatar_url: url })
  }

  // No bucket bound (local or a preview build): fall back to the old behaviour so
  // uploads still work rather than failing outright.
  await c.env.DB.prepare('UPDATE attendees SET avatar_url = ? WHERE id = ?').bind(image, id).run()
  return c.json({ success: true, avatar_url: image })
})

// Serves anything written to the bucket. Public by design: these are profile photos
// already shown in the attendee directory, and the key carries a timestamp so it is
// not guessable from an attendee id alone.
app.get('/api/uploads/*', async (c) => {
  if (!c.env.UPLOADS) return c.json({ error: 'Uploads not configured' }, 404)
  const key = c.req.path.replace('/api/uploads/', '')
  if (!key || key.includes('..')) return c.json({ error: 'Not found' }, 404)
  const obj = await c.env.UPLOADS.get(key)
  if (!obj) return c.json({ error: 'Not found' }, 404)
  const h = new Headers()
  obj.writeHttpMetadata(h)
  h.set('etag', obj.httpEtag)
  h.set('cache-control', 'public, max-age=31536000, immutable')
  return new Response(obj.body, { headers: h })
})

