// Exhibitor lead console: everyone who visited / showed interest in this
// attendee's booth, plus a summary. Powers the exhibitor lead-capture view.
app.get('/api/attendees/:id/exhibitor/leads', async (c) => {
  const id = c.req.param('id')
  const denied = await requireSelf(c, id); if (denied) return denied
  const exhibitor = await c.env.DB.prepare('SELECT id, company_name, booth_number FROM exhibitors WHERE attendee_id = ?').bind(id).first() as any
  if (!exhibitor) return c.json({ exhibitor: null, leads: [], summary: { total: 0, interested: 0 } })
  const { results: leads } = await c.env.DB.prepare(`
    SELECT bv.id, bv.interested, bv.notes, bv.visited_at,
           a.name, a.email, a.company, a.job_title, a.avatar_url, a.linkedin_url, a.badge_type
    FROM booth_visits bv JOIN attendees a ON bv.attendee_id = a.id
    WHERE bv.exhibitor_id = ? ORDER BY bv.visited_at DESC
  `).bind(exhibitor.id).all()
  const interested = (leads || []).filter((l: any) => l.interested).length
  return c.json({ exhibitor, leads: leads || [], summary: { total: (leads || []).length, interested } })
})

// Create or update exhibitor booth for an attendee (self-service)
app.put('/api/attendees/:id/exhibitor', async (c) => {
  const attendeeId = c.req.param('id')
  const denied = await requireSelf(c, attendeeId); if (denied) return denied
  const body = await c.req.json()
  const { company_name, description, booth_number, booth_size, category, website_url, contact_email, contact_phone, products } = body

  // Check if attendee has exhibitor-related badge
  const attendee = await c.env.DB.prepare('SELECT * FROM attendees WHERE id = ?').bind(attendeeId).first() as any
  if (!attendee) return c.json({ error: 'Attendee not found' }, 404)

  const exhibitorBadges = ['Exhibitor', 'Exhibitor Booth', 'Exhibition Speaker']
  const hasExhibitorBadge = exhibitorBadges.some(b => (attendee.badge_type || '').toLowerCase().includes(b.toLowerCase()))
  if (!hasExhibitorBadge) return c.json({ error: 'Only exhibitor badge holders can manage booths' }, 403)

  // Check if exhibitor already exists for this attendee
  const existing = await c.env.DB.prepare('SELECT id FROM exhibitors WHERE attendee_id = ?').bind(attendeeId).first()

  if (existing) {
    await c.env.DB.prepare(
      'UPDATE exhibitors SET company_name=?, description=?, booth_number=?, booth_size=?, category=?, website_url=?, contact_email=?, contact_phone=?, products=? WHERE attendee_id=?'
    ).bind(company_name, description || '', booth_number || '', booth_size || 'standard', category || '', website_url || '', contact_email || '', contact_phone || '', products || '', attendeeId).run()
  } else {
    await c.env.DB.prepare(
      'INSERT INTO exhibitors (event_id, company_name, description, booth_number, booth_size, category, website_url, contact_email, contact_phone, products, attendee_id) VALUES (?,?,?,?,?,?,?,?,?,?,?)'
    ).bind(attendee.event_id, company_name, description || '', booth_number || '', booth_size || 'standard', category || '', website_url || '', contact_email || '', contact_phone || '', products || '', attendeeId).run()
  }

  const updated = await c.env.DB.prepare('SELECT * FROM exhibitors WHERE attendee_id = ?').bind(attendeeId).first()
  return c.json(updated)
})

// ==================== STATS APIs ====================

app.get('/api/events/:id/stats', async (c) => {
  const eventId = c.req.param('id')

  // Seven sequential awaits were seven round trips to D1 (measured 1,325ms). Six of
  // them go in ONE batch. The checked-in count stays OUT of it deliberately:
  // batch() is all-or-nothing, so if checked_in_at were ever missing on this
  // database the whole overview would 500 instead of degrading to 0. It runs
  // concurrently with the batch, keeping its own tolerance, so this is two round
  // trips rather than seven.
  const [rows, checkedInCount] = await Promise.all([
    c.env.DB.batch([
      c.env.DB.prepare('SELECT COUNT(*) as count FROM attendees WHERE event_id = ?').bind(eventId),
      // is_online is written as 1 at registration and at every sign-in and is never
      // set back to 0, so this stat read 1325 of 1325 for the life of the app.
      // Derive presence from the last sign-in instead - the same window and the same
      // reasoning as ATTENDEE_PUBLIC_COLS, so the tile and the presence dots agree.
      c.env.DB.prepare(`SELECT COUNT(*) as count FROM attendees WHERE event_id = ? AND last_login_at > datetime('now', '-${ONLINE_WINDOW_MINUTES} minutes')`).bind(eventId),
      c.env.DB.prepare('SELECT COUNT(*) as count FROM sessions WHERE event_id = ?').bind(eventId),
      c.env.DB.prepare('SELECT COUNT(*) as count FROM exhibitors WHERE event_id = ?').bind(eventId),
      c.env.DB.prepare('SELECT COUNT(*) as count FROM connections WHERE event_id = ?').bind(eventId),
      c.env.DB.prepare('SELECT COUNT(*) as count FROM award_categories WHERE event_id = ?').bind(eventId),
    ]),
    (async () => {
      try {
        const r = await c.env.DB.prepare(
          'SELECT COUNT(*) as count FROM attendees WHERE event_id = ? AND checked_in_at IS NOT NULL'
        ).bind(eventId).first() as any
        return r?.count || 0
      } catch (_) { return 0 }
    })(),
  ])

  const n = (i: number) => ((rows[i] as any)?.results?.[0]?.count) || 0

  // This route is unauthenticated - it answers the app's dashboard - so it was
  // handing the exact registration count to anyone who asked for it, and a single
  // curl was all it took. Below the threshold the field comes back null rather
  // than being dropped, so existing callers keep the same response shape and can
  // tell "withheld" apart from "zero".
  //
  // checked_in is withheld on the same terms. It is a headcount of the same people
  // by another name, and on the two event days it would answer the question this
  // is meant to close just as directly.
  const attendeeTotal = n(0)
  const reveal = mayRevealCount(c, attendeeTotal)

  return c.json({
    attendees: reveal ? attendeeTotal : null,
    attendees_withheld: reveal ? undefined : true,
    online: n(1),
    checkedIn: reveal ? checkedInCount : null,
    sessions: n(2),
    exhibitors: n(3),
    connections: n(4),
    categories: n(5),
  })
})

