// Admin: Add single attendee
app.post('/api/admin/attendees', async (c) => {
  const body = await c.req.json()
  const { event_id, name, email, company, badge_type } = body
  if (!name || !email) return c.json({ error: 'Name and email are required' }, 400)
  const normalizedEmail = email.trim().toLowerCase()

  // Built from the same field list as the edit paths and intersected with the real
  // schema, so a column the migrations never added cannot fail the whole insert -
  // which is what made Add Attendee reject every submission.
  const cols = await attendeeColumns(c)
  const nowStamp = new Date().toISOString().slice(0, 19).replace('T', ' ')
  const fallbacks: Record<string, any> = {
    lunch_inclusion: 'Yes', role: 'attendee', badge_type: 'Delegate', country: 'India',
    // A row with no registration_date sorts to the bottom of a newest-first list -
    // exactly the row an admin just added and wants to see.
    registration_date: nowStamp,
  }
  const names: string[] = ['event_id', 'name', 'email']
  const vals: any[] = [event_id, name.trim(), normalizedEmail]
  for (const f of ADMIN_ATTENDEE_FIELDS) {
    if (f === 'name' || f === 'email' || !cols.has(f)) continue
    const v = body[f]
    names.push(f)
    vals.push(v === undefined || v === null || v === '' ? (fallbacks[f] ?? '') : sanitizeAttendeeField(f, v))
  }
  names.push('is_online')
  vals.push(0)

  try {
    const result = await c.env.DB.prepare(
      `INSERT INTO attendees (${names.join(', ')}) VALUES (${names.map(() => '?').join(', ')})`
    ).bind(...vals).run()

    const attendee = await c.env.DB.prepare('SELECT * FROM attendees WHERE id = ?').bind(result.meta.last_row_id).first()

    // Auto-create exhibitor if badge is exhibitor-related
    const exhibitorBadges = ['exhibitor', 'exhibitor booth', 'exhibition speaker']
    if (exhibitorBadges.some(b => (badge_type || '').toLowerCase().includes(b))) {
      await c.env.DB.prepare(
        'INSERT INTO exhibitors (event_id, company_name, contact_email, attendee_id) VALUES (?,?,?,?)'
      ).bind(event_id, company || name.trim(), normalizedEmail, result.meta.last_row_id).run()
    }

    return c.json(attendee, 201)
  } catch (e: any) {
    if (e.message?.includes('UNIQUE')) {
      return c.json({ error: 'An attendee with this email already exists' }, 409)
    }
    return c.json({ error: 'Failed to add attendee: ' + e.message }, 400)
  }
})

// Admin: Bulk upload attendees (receives parsed JSON array from frontend)
// Apply one field change to many attendees at once. Whitelisted through the same
// ADMIN_ATTENDEE_FIELDS and sanitiser the single-row handlers use, and intersected
// with the live schema so a missing column cannot fail the statement silently.
app.post('/api/admin/attendees/bulk-update', async (c) => {
  const body = await c.req.json().catch(() => ({})) as any
  const ids: any[] = Array.isArray(body.ids) ? body.ids.slice(0, 2000) : []
  const changes = body.changes && typeof body.changes === 'object' ? body.changes : {}
  if (!ids.length) return c.json({ error: 'No attendees selected.' }, 400)
  const cols = await attendeeColumns(c)
  const sets: string[] = []
  const vals: any[] = []
  for (const f of ADMIN_ATTENDEE_FIELDS) {
    if (!(f in changes) || !cols.has(f)) continue
    sets.push(`${f} = ?`)
    vals.push(sanitizeAttendeeField(f, changes[f]))
  }
  if (!sets.length) return c.json({ error: 'Nothing to change.' }, 400)
  const numericIds = ids.map((v) => parseInt(String(v), 10)).filter((n) => Number.isFinite(n))
  if (!numericIds.length) return c.json({ error: 'No valid attendee ids.' }, 400)
  const placeholders = numericIds.map(() => '?').join(',')
  await c.env.DB.prepare(`UPDATE attendees SET ${sets.join(', ')} WHERE id IN (${placeholders})`)
    .bind(...vals, ...numericIds).run()
  await audit(c, 'attendees.bulk-update', 'attendee', numericIds.join(','), { count: numericIds.length, changes })
  return c.json({ success: true, updated: numericIds.length })
})

// Delete many. Kept separate from the update path so it cannot be reached by a
// stray field name, and audited with the emails so the rows can be identified
// afterwards from the log alone.
app.post('/api/admin/attendees/bulk-delete', async (c) => {
  const body = await c.req.json().catch(() => ({})) as any
  const ids: any[] = Array.isArray(body.ids) ? body.ids.slice(0, 500) : []
  const numericIds = ids.map((v) => parseInt(String(v), 10)).filter((n) => Number.isFinite(n))
  if (!numericIds.length) return c.json({ error: 'No attendees selected.' }, 400)
  const placeholders = numericIds.map(() => '?').join(',')
  const { results: doomed } = await c.env.DB.prepare(
    `SELECT id, name, email FROM attendees WHERE id IN (${placeholders})`).bind(...numericIds).all()
  await c.env.DB.prepare(`DELETE FROM attendees WHERE id IN (${placeholders})`).bind(...numericIds).run()
  await audit(c, 'attendees.bulk-delete', 'attendee', numericIds.join(','), { deleted: doomed })
  return c.json({ success: true, deleted: numericIds.length })
})

// One attendee's whole story: registered, notified, signed in, paid, checked in.
// The tab could only ever show a row; answering "what happened with this person"
// meant reading five columns and guessing.
app.get('/api/admin/attendees/:id/timeline', async (c) => {
  const id = c.req.param('id')
  const a = await c.env.DB.prepare('SELECT * FROM attendees WHERE id = ?').bind(id).first() as any
  if (!a) return c.json({ error: 'Attendee not found' }, 404)
  const ev: { at: string; label: string; kind: string }[] = []
  const add = (at: any, label: string, kind: string) => { if (at) ev.push({ at: String(at), label, kind }) }
  add(a.registration_date || a.created_at, 'Registered' + (a.registration_source ? ' via ' + a.registration_source : ''), 'register')
  add(a.notified_at, 'Sent the account-ready email', 'email')
  add(a.profile_reminder_sent_at, 'Sent a profile reminder', 'email')
  add(a.rsvp_at, 'RSVP: ' + (a.rsvp_status || 'responded'), 'rsvp')
  add(a.last_login_at, 'Signed in to the app', 'login')
  add(a.pass_downloaded_at, 'Downloaded their pass', 'pass')
  add(a.checked_in_at, 'Checked in at the desk' + (a.checked_in_by ? ' by ' + a.checked_in_by : ''), 'checkin')
  ev.sort((x, y) => String(x.at).localeCompare(String(y.at)))
  let invoices: any[] = []
  try {
    const r = await c.env.DB.prepare(
      'SELECT id, invoice_no, total, emailed_at, paid_at FROM invoices WHERE attendee_id = ? ORDER BY id DESC').bind(id).all()
    invoices = (r.results as any[]) || []
  } catch (_) { invoices = [] }
  return c.json({ attendee: a, timeline: ev, invoices })
})

app.post('/api/admin/attendees/bulk', async (c) => {
  const { event_id, attendees } = await c.req.json()
  if (!Array.isArray(attendees) || attendees.length === 0) {
    return c.json({ error: 'No attendees data provided' }, 400)
  }
  if (attendees.length > 500) {
    return c.json({ error: 'Maximum 500 attendees per upload' }, 400)
  }

  const results = { imported: 0, skipped: 0, errors: [] as string[] }

  for (const a of attendees) {
    if (!a.name || !a.email) {
      results.errors.push(`Row missing name or email: ${a.name || '?'} / ${a.email || '?'}`)
      results.skipped++
      continue
    }
    const email = a.email.trim().toLowerCase()
    try {
      // city, country and industry are parsed out of the CSV by the uploader but were
      // never in this statement, so every bulk-imported attendee landed with those
      // three blank no matter what the spreadsheet said.
      await c.env.DB.prepare(
        'INSERT INTO attendees (event_id, name, email, company, job_title, bio, interests, linkedin_url, mobile, lunch_inclusion, role, badge_type, city, country, industry, registration_date, is_online) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)'
      ).bind(
        event_id,
        a.name.trim(),
        email,
        a.company?.trim() || '',
        a.job_title?.trim() || '',
        a.bio?.trim() || '',
        a.interests?.trim() || '',
        a.linkedin_url?.trim() || '',
        a.mobile?.trim() || '',
        a.lunch_inclusion?.trim() || 'Yes',
        a.role?.trim() || 'attendee',
        a.badge_type?.trim() || 'Delegate',
        a.city?.trim() || '',
        a.country?.trim() || 'India',
        INDUSTRIES.includes(String(a.industry || '').trim()) ? String(a.industry).trim() : '',
        a.registration_date?.trim() || new Date().toISOString().slice(0, 19).replace('T', ' ')
      ).run()
      results.imported++
    } catch (e: any) {
      if (e.message?.includes('UNIQUE')) {
        results.errors.push(`Duplicate email: ${email}`)
        results.skipped++
      } else {
        results.errors.push(`Failed to import ${a.name}: ${e.message}`)
        results.skipped++
      }
    }
  }

  return c.json(results)
})

// Admin: Download attendees as CSV
app.get('/api/admin/events/:id/attendees/export', async (c) => {
  const eventId = c.req.param('id')

  // This file is where the complete record lives - the admin grid deliberately
  // carries only what it draws - so it exports every column worth having. The
  // original order is preserved and later additions are appended, so anything
  // parsing the file by position keeps working. avatar_url is left out on purpose:
  // an uploaded photo is stored inline, and one row would be tens of KB of base64.
  const EXPORT_COLS = [
    'name', 'email', 'company', 'job_title', 'mobile', 'city', 'country',
    'linkedin_url', 'lunch_inclusion', 'arrival_time', 'bio', 'interests', 'role',
    'badge_type', 'registration_date', 'payment_amount', 'rsvp_status', 'rsvp_at',
    'notified_at', 'last_login_at', 'pass_downloaded_at', 'social_card_downloaded_at', 'company_logo_url', 'registration_source',
    'id', 'payment_status', 'industry', 'company_size', 'special_requirements',
    'pass_type', 'twitter_url', 'website_url', 'checked_in_at', 'checked_in_by',
    'created_at',
  ]
  // payment_amount was in the header row but never in the SELECT, so that column
  // came out blank on every row. Naming columns outright would fail the whole
  // export with "no such column" on a database one migration behind, so the list
  // is intersected with the table as it actually is - the same guard the admin
  // write path uses, and each column starts exporting the day a migration adds it.
  const have = await attendeeColumns(c)
  const headers = EXPORT_COLS.filter(h => have.has(h))
  if (!headers.length) return c.json({ error: 'attendees table unavailable' }, 503)

  // A download that fails should say so in a way the browser can show, not hand
  // the operator a 500 page saved as attendees_export.csv.
  let results: any[]
  try {
    const r = await c.env.DB.prepare(
      `SELECT ${headers.join(', ')} FROM attendees WHERE event_id = ? ORDER BY id`
    ).bind(eventId).all()
    results = (r.results || []) as any[]
  } catch {
    return c.json({ error: 'Could not read the attendees table.' }, 503)
  }

  const csvRows = [headers.join(',')]
  for (const r of (results || []) as any[]) {
    csvRows.push(headers.map(h => {
      const val = (r[h] == null ? '' : r[h]).toString().replace(/"/g, '""')
      return /[",\r\n]/.test(val) ? `"${val}"` : val
    }).join(','))
  }

  // The rows used to be joined with a literal backslash-n rather than a newline,
  // so the entire export arrived as ONE line and every spreadsheet opened it as a
  // single record. CRLF and a BOM, so Excel on Windows reads both the row breaks
  // and the accents in the names.
  return new Response('\uFEFF' + csvRows.join('\r\n'), {
    headers: {
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': 'attachment; filename="attendees_export.csv"'
    }
  })
})

