app.post('/api/admin/campaigns/:id/pause', async (c) => {
  const id = c.req.param('id')
  await c.env.DB.prepare("UPDATE campaigns SET status = 'paused', updated_at = datetime('now') WHERE id = ? AND status = 'running'").bind(id).run()
  await audit(c, 'campaign.pause', 'campaign', id)
  return c.json({ success: true })
})

app.post('/api/admin/campaigns/:id/resume', async (c) => {
  const id = c.req.param('id')
  // A row left as 'sending' belonged to a request that never came back - the tab
  // was closed mid-send. Put those back in the queue.
  await c.env.DB.prepare("UPDATE campaign_recipients SET status = 'pending' WHERE campaign_id = ? AND status = 'sending'").bind(id).run()
  await c.env.DB.prepare("UPDATE campaigns SET status = 'running', finished_at = NULL, updated_at = datetime('now') WHERE id = ?").bind(id).run()
  await audit(c, 'campaign.resume', 'campaign', id)
  return c.json({ success: true })
})

// Queue the failures of a finished campaign again, as a fresh campaign.
app.post('/api/admin/campaigns/:id/retry-failed', async (c) => {
  const id = c.req.param('id')
  const camp = await c.env.DB.prepare('SELECT * FROM campaigns WHERE id = ?').bind(id).first() as any
  if (!camp) return c.json({ error: 'Campaign not found' }, 404)
  const { results } = await c.env.DB.prepare(
    "SELECT attendee_id, email, name FROM campaign_recipients WHERE campaign_id = ? AND status = 'failed' ORDER BY id"
  ).bind(id).all()
  const rows = (results as any[]) || []
  if (!rows.length) return c.json({ error: 'Nothing failed on that campaign.' }, 400)
  const who = adminActor(c)
  const ins = await c.env.DB.prepare(
    'INSERT INTO campaigns (kind, title, ref_id, audience, status, total, created_by) VALUES (?,?,?,?,?,?,?)'
  ).bind(camp.kind, 'Retry: ' + (camp.title || camp.kind), camp.ref_id, 'retry', 'running', rows.length, who.actor).run()
  const newId = ins.meta.last_row_id
  for (let i = 0; i < rows.length; i += 50) {
    const chunk = rows.slice(i, i + 50)
    const values = chunk.map(() => '(?,?,?,?)').join(',')
    const binds: any[] = []
    chunk.forEach((r) => binds.push(newId, r.attendee_id, r.email, r.name || ''))
    await c.env.DB.prepare(
      `INSERT INTO campaign_recipients (campaign_id, attendee_id, email, name) VALUES ${values}`
    ).bind(...binds).run()
  }
  await audit(c, 'campaign.retry-failed', 'campaign', newId, { from: id, total: rows.length })
  return c.json({ id: newId, total: rows.length }, 201)
})

// Admin: Advanced analytics
app.get('/api/admin/events/:id/analytics', async (c) => {
  const eventId = c.req.param('id')
  
  const attendeesByRole = await c.env.DB.prepare('SELECT role, COUNT(*) as count FROM attendees WHERE event_id=? GROUP BY role').bind(eventId).all()
  const attendeesByBadge = await c.env.DB.prepare('SELECT badge_type, COUNT(*) as count FROM attendees WHERE event_id=? GROUP BY badge_type').bind(eventId).all()
  const sessionsByType = await c.env.DB.prepare('SELECT session_type, COUNT(*) as count FROM sessions WHERE event_id=? GROUP BY session_type').bind(eventId).all()
  const sessionsByTrack = await c.env.DB.prepare('SELECT track, COUNT(*) as count FROM sessions WHERE event_id=? AND track IS NOT NULL GROUP BY track').bind(eventId).all()
  const connectionsByStatus = await c.env.DB.prepare('SELECT status, COUNT(*) as count FROM connections WHERE event_id=? GROUP BY status').bind(eventId).all()
  const meetingsByStatus = await c.env.DB.prepare('SELECT status, COUNT(*) as count FROM meetings WHERE event_id=? GROUP BY status').bind(eventId).all()
  const topExhibitors = await c.env.DB.prepare('SELECT company_name, visitor_count, booth_size FROM exhibitors WHERE event_id=? ORDER BY visitor_count DESC LIMIT 10').bind(eventId).all()
  const topNominees = await c.env.DB.prepare('SELECT n.name, n.company, c.name as category_name, n.is_winner FROM award_nominees n JOIN award_categories c ON n.category_id=c.id WHERE n.event_id=? ORDER BY n.is_winner DESC, n.name ASC LIMIT 10').bind(eventId).all()
  const messageCount = await c.env.DB.prepare('SELECT COUNT(*) as count FROM messages WHERE event_id=?').bind(eventId).first()
  const boothVisitCount = await c.env.DB.prepare('SELECT COUNT(*) as count FROM booth_visits WHERE event_id=?').bind(eventId).first()
  const exhibitorsByCategory = await c.env.DB.prepare('SELECT category, COUNT(*) as count FROM exhibitors WHERE event_id=? GROUP BY category').bind(eventId).all()
  const recentRegistrations = await c.env.DB.prepare('SELECT id, name, email, company, job_title, role, badge_type, created_at FROM attendees WHERE event_id=? ORDER BY created_at DESC LIMIT 10').bind(eventId).all()

  return c.json({
    attendeesByRole: attendeesByRole.results,
    attendeesByBadge: attendeesByBadge.results,
    sessionsByType: sessionsByType.results,
    sessionsByTrack: sessionsByTrack.results,
    connectionsByStatus: connectionsByStatus.results,
    meetingsByStatus: meetingsByStatus.results,
    topExhibitors: topExhibitors.results,
    topNominees: topNominees.results,
    messageCount: (messageCount as any)?.count || 0,
    boothVisitCount: (boothVisitCount as any)?.count || 0,
    exhibitorsByCategory: exhibitorsByCategory.results,
    recentRegistrations: recentRegistrations.results,
  })
})

// Registrations per day, where they came from, and how far each pass tier gets
// down the funnel. Everything here is one pass over attendees.
app.get('/api/admin/events/:id/growth', async (c) => {
  const eventId = c.req.param('id')
  const dateExpr = "substr(COALESCE(registration_date, created_at), 1, 10)"
  const daily = await c.env.DB.prepare(
    `SELECT ${dateExpr} AS day, COUNT(*) AS count FROM attendees
      WHERE event_id = ? AND COALESCE(registration_date, created_at) IS NOT NULL
      GROUP BY day ORDER BY day`
  ).bind(eventId).all()
  const bySource = await c.env.DB.prepare(
    `SELECT COALESCE(NULLIF(registration_source,''), 'unknown') AS source, COUNT(*) AS count
       FROM attendees WHERE event_id = ? GROUP BY source ORDER BY count DESC`
  ).bind(eventId).all()
  const byCity = await c.env.DB.prepare(
    `SELECT COALESCE(NULLIF(city,''), 'unknown') AS city, COUNT(*) AS count
       FROM attendees WHERE event_id = ? GROUP BY city ORDER BY count DESC LIMIT 12`
  ).bind(eventId).all()
  // The funnel every organiser asks about: of the people holding each pass, how
  // many were told, signed in, took their pass, told their network, and turned up.
  //
  // The social-card column is spliced in only once the schema actually has it.
  // Naming it outright would answer 500 for the WHOLE statistics endpoint on a
  // database one migration behind - not one blank column, the entire dashboard -
  // so it degrades to a hard zero instead, exactly as the CSV export intersects
  // its column list with the live table.
  const statCols = await attendeeColumns(c)
  const cardTaken = statCols.has('social_card_downloaded_at')
    ? `SUM(CASE WHEN social_card_downloaded_at IS NOT NULL THEN 1 ELSE 0 END)`
    : `0`
  const funnel = await c.env.DB.prepare(
    `SELECT COALESCE(NULLIF(badge_type,''),'Unspecified') AS badge_type,
            COUNT(*) AS registered,
            SUM(CASE WHEN notified_at IS NOT NULL THEN 1 ELSE 0 END) AS notified,
            SUM(CASE WHEN last_login_at IS NOT NULL THEN 1 ELSE 0 END) AS signed_in,
            SUM(CASE WHEN pass_downloaded_at IS NOT NULL THEN 1 ELSE 0 END) AS pass_taken,
            ${cardTaken} AS card_taken,
            SUM(CASE WHEN checked_in_at IS NOT NULL THEN 1 ELSE 0 END) AS checked_in
       FROM attendees WHERE event_id = ? GROUP BY badge_type ORDER BY registered DESC`
  ).bind(eventId).all()
  const profile = await c.env.DB.prepare(
    `SELECT COUNT(*) AS total,
            SUM(CASE WHEN company IS NULL OR company = '' THEN 1 ELSE 0 END) AS no_company,
            SUM(CASE WHEN job_title IS NULL OR job_title = '' THEN 1 ELSE 0 END) AS no_title,
            SUM(CASE WHEN city IS NULL OR city = '' THEN 1 ELSE 0 END) AS no_city,
            SUM(CASE WHEN mobile IS NULL OR mobile = '' THEN 1 ELSE 0 END) AS no_mobile,
            SUM(CASE WHEN avatar_url IS NULL OR avatar_url = '' THEN 1 ELSE 0 END) AS no_photo
       FROM attendees WHERE event_id = ?`
  ).bind(eventId).first()
  return c.json({
    daily: daily.results || [],
    bySource: bySource.results || [],
    byCity: byCity.results || [],
    funnel: funnel.results || [],
    profile: profile || {},
  })
})

// Admin: Bulk operations
app.post('/api/admin/events/:id/broadcast', async (c) => {
  const eventId = c.req.param('id')
  const { title, content, announcement_type, author_name, email_it, audience } = await c.req.json()
  const result = await c.env.DB.prepare(
    'INSERT INTO announcements (event_id, title, content, announcement_type, author_name, pinned) VALUES (?,?,?,?,?,1)'
  ).bind(eventId, title, content, announcement_type || 'urgent', author_name || 'Event Admin').run()
  await audit(c, 'announcement.broadcast', 'announcement', result.meta.last_row_id, { title, email_it: !!email_it, audience })
  // Posting a pinned notice only reaches people already in the app. When the
  // operator asks for it, return the recipient list so the panel can send too.
  let recipients: any[] = []
  if (email_it) {
    const who = audience === 'checked_in'
      ? 'AND checked_in_at IS NOT NULL'
      : audience === 'confirmed' ? "AND rsvp_status = 'confirmed'" : ''
    const r = await c.env.DB.prepare(
      `SELECT id, name, email FROM attendees WHERE event_id = ? AND email IS NOT NULL AND email != '' ${who} ORDER BY id`
    ).bind(eventId).all()
    recipients = (r.results as any[]) || []
  }
  return c.json({ id: result.meta.last_row_id, success: true, recipients, count: recipients.length }, 201)
})

// Send one announcement to one attendee. The panel walks the recipient list it
// got back from the broadcast, so a long send reports progress and one bad
// address cannot stop the rest.
app.post('/api/admin/announcements/:id/email/:attendeeId', async (c) => {
  const annId = c.req.param('id')
  const attId = c.req.param('attendeeId')
  const ann = await c.env.DB.prepare('SELECT * FROM announcements WHERE id = ?').bind(annId).first() as any
  if (!ann) return c.json({ error: 'Announcement not found' }, 404)
  const att = await c.env.DB.prepare('SELECT id, name, email FROM attendees WHERE id = ?').bind(attId).first() as any
  if (!att?.email) return c.json({ error: 'Attendee has no email' }, 404)
  const esc = (v: any) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  const urgent = String(ann.announcement_type || '') === 'urgent'
  const html = `<!DOCTYPE html><html><body style="margin:0;background:#f6f7fb;padding:24px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1e2140">
  <div style="max-width:600px;margin:0 auto;background:#fff;border-radius:14px;padding:28px;border:1px solid ${urgent ? '#f3c2c2' : '#e7e9f5'}">
    ${urgent ? '<div style="display:inline-block;background:#fdecec;color:#b42318;font-size:12px;font-weight:700;padding:4px 10px;border-radius:999px;margin-bottom:12px">IMPORTANT</div>' : ''}
    <h2 style="margin:0 0 12px;font-size:20px">${esc(ann.title)}</h2>
    <p style="font-size:15px;line-height:1.65;white-space:pre-wrap">${esc(ann.content)}</p>
    <p style="margin:22px 0 0;font-size:14px;color:#555">Team Bharat AI Innovation<br>
      <span style="color:#888">20-21 November 2026 &middot; World Trade Center, Mumbai</span></p>
  </div></body></html>`
  const sent = await sendAdminEmail(c, att.email, (urgent ? '[Important] ' : '') + String(ann.title || 'Update'), html)
  if (!sent.ok) return c.json({ error: sent.error }, 502)
  return c.json({ success: true })
})

